quests[9456] = { id = 9456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nightstalker Clean Up, Isle 2...", description = "I'm not going to make any excuses for what you've found. This is clearly our fault. We had gotten reports of crushed crystal fragments showing up in the river to the east but chose to ignore the implications. Now we can either sit around on this island and cry about the tragedy that has befallen this land or we can do something about it and prevent it from spreading.\n\nIf you've got the stomach for it, I want you to go back into the wilds and kill as many of the infected nightstalkers as you can find.", sourceObjective = "Exarch Menelaous at Azure Watch has asked that you slay 8 Infected Nightstalker Runts.", progress = "We can't risk this contamination spreading. The reports I've heard come from Blood Watch are bad enough. This has to be stopped now!", completion = "I just hope it's not too late...", sourceObjectiveStatus = "unverified-source-field" }
quests[9457] = { id = 9457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unusual Patron", description = "So this Naias is the mastermind behind the Bloodscalp and their exotic magic? I'll admit, this is the last place I expected my inquiry to lead, but no matter, our findings may still prove useful.\n\nOff the coast to the northwest is an island inhabited by lesser water elementals. There's a crude stone slab there that might serve as an altar for the likes of the trolls. Take the totem you found to that altar. Let's see if we can draw this Naias out and distill his power into a more agreeable form.", sourceObjective = "Use the Gift of Naias near the Altar of Naias to summon the water elemental Naias. Defeat him and return to Nemeth Hawkeye at Grom'gol Base Camp with the Heart of Naias.", progress = "What news of Naias, {name}?", completion = "I can feel the raw power contained in this gem, {name}. I'll send it to Silvermoon for our magisters to study further, but I am sure it will prove useful in our struggle against the Amani.\n\nYour help has been invaluable in procuring this gem, and I will see to it that the Farstriders know the name of the {race} who made this find possible.", sourceObjectiveStatus = "unverified-source-field" }
quests[9460] = { id = 9460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Combining Forces", description = "Keltus Darkleaf reporting for duty!\n\nOh... who are you, anyhow?  If you are here for my report, I insist you help me first.\n\nI am planning to attack the sentinel spies, but I intend to send in my faithful Whisper as a first strike.  She just needs a scent to hone in on them.\n\nSurely someone of your skill could sneak in and steal something from the sentinel leader?", sourceObjective = "Keltus Darkleaf wants you to pickpocket the Lacy Handkerchief from the Sentinel Leader and bring it to him.", progress = "Did you get something?", completion = "Excellent!  Such a personal item carries a strong scent of the intruders--enough to guide Whisper into their ranks...", sourceObjectiveStatus = "unverified-source-field" }
quests[9461] = { id = 9461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Fire", description = "You should know that The Prophet has been asking for you, having heard of your success in your trial. The creation of your fire totem will have to wait until you have spoken with him.\n\nThis is a rare honor; you must hurry to the Exodar to see him at once!", sourceObjective = "Seek out Prophet Velen at the Vault of Lights in the Exodar.", completion = "Hello, {name}, I have been expecting you.  I trust this day finds you well?", sourceObjectiveStatus = "unverified-source-field" }
quests[9462] = { id = 9462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Fire", description = "{name}! It is time for you to receive further training in the ways of the spirits. You should seek out Tuluun, the shaman at Azure Watch. He can begin your introduction to understanding and harnessing the power of flame.", sourceObjective = "Speak with Tuluun at Azure Watch on Azuremyst Isle.", completion = "Just in time, {name}. I hope you are ready to continue your training. This next task will be a difficult one.", sourceObjectiveStatus = "unverified-source-field" }
quests[9463] = { id = 9463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Medicinal Purpose", description = "I have found that lashers milling about on the island hold restorative medicinal properties in their vines. Through proper treatment, the vines can be broken down into a powerful healing ointment. Unfortunately, with so many injured draenei passing through Azure Watch, we are always in short supply.\n\nOur delicate guest was found injured and unconscious by the Crystalbrook only yesterday. If you bring me vines, we may be able to save her.\n\nYou will find root trappers both south and east of Azure Watch.", sourceObjective = "Anchorite Fateema at Azure Watch wants you to bring her 8 Root Trapper Vines.", progress = "I fear that her health is in steady decline.", completion = "Let us hope that this ointment will strengthen her spirit!", sourceObjectiveStatus = "unverified-source-field" }
quests[9464] = { id = 9464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Fire", description = "Once again you are to be tested, and this time the chaotic element of fire must be understood if you're to create a totem to harness its energies.\n\nTo the northeast on the coast is a sacred place of fire known as Emberglade. Amidst its burned trees stands Temper, a fire elemental of great power, and the one that you must speak with.\n\nGo to him now and may the elemental spirits of Azeroth go with you.", sourceObjective = "Speak with Temper at Emberglade on Azuremyst Isle.", completion = "I trust that the burning I see behind your eyes is from a desire to grow and understand?  Good!\n\nTuluun has sent you here because he sees your potential to both learn and help with a problem that the crash of your Exodar has caused.\n\nWe shall see.", sourceObjectiveStatus = "unverified-source-field" }
quests[9465] = { id = 9465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Fire", description = "One of my brethren, Hauteur, has gone insane, no doubt because of the crash of your ship.  He's begun demanding that the local owlbeasts worship him.\n\nThis will not continue!  None of us would ever impersonate a god!  It falls to you to restore the balance.\n\nFirst, you must retrieve their ritual torch, which has been taken by the crazed wildkin inside Stillpine Hold to the west.\n\nReturn the torch to me.", sourceObjective = "Retrieve the Ritual Torch and return it to Temper at Emberglade on Azuremyst Isle.", progress = "You have the torch?", completion = "See how its fire never goes out?  That is the work of Hauteur.  It is a symbol of his arrogance.  Flame is meant to consume that which it burns and then itself die, to be reborn anew another time.\n\nI would help you douse the torch, but it must stay lit for you to deal with Hauteur.  We will let it burn a little while longer.", sourceObjectiveStatus = "unverified-source-field" }
quests[9466] = { id = 9466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Blacktalon the Savage", description = "By order of the Ranger Captain, a reward is hereby offered for the slaying of the vicious rockflayer matriarch known as Blacktalon the Savage.\n\nBlacktalon was last sighted inside a cave in the Great Fissure.  Individuals seeking the reward are to present the creature's claws as proof of the deed.", sourceObjective = "Bring Blacktalon's Claws to Ranger Captain Venn'ren at Falcon Watch in Hellfire Peninsula.", progress = "You have news regarding Blacktalon?", completion = "You're a brave {class}, {name}.  That savage beast took many of my best hunters' lives.\n\nTake this reward, you've earned it.", sourceObjectiveStatus = "unverified-source-field" }
quests[9467] = { id = 9467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Fire", description = "The owlbeasts of Moonwing Den on Silvermyst Isle, far to the southwest, have been deluded into thinking that Hauteur is a god to be worshipped.  What he truly is, is a fallen elemental who needs to be put out of his misery.  That torch is the key to his downfall.\n\nHauteur regularly demands that these owlbeasts burn an effigy in his honor.  So, when you light it, he will come.  Slay him and bring me the ashes.  Then use the orb in the satchel that I will give you to return to me here.", sourceObjective = "Retrieve Hauteur's Ashes and then return them and the Ritual Torch to Temper at Emberglade on Azuremyst Isle. Remember that you can use the Orb of Returning to teleport back to Temper once you have the ashes.", progress = "Do not speak to me again until you have Hauteur's ashes.", completion = "It is a valuable lesson that you learn here today.  It is the story of endings and new beginnings.\n\nWhen first we spoke I told you that fire was not just destruction, but also a renewing force of the elements.  Through your actions you have both destroyed and saved Hauteur, for he shall be reborn from his ashes.", sourceObjectiveStatus = "unverified-source-field" }
quests[9468] = { id = 9468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Fire", description = "You have done a great thing here today in your pursuit of understanding your relationship to the flame.  Remember to always treat it with the utmost respect lest you get burned.\n\nI saved a portion of Hauteur's ashes for you.  Use them in the creation of your fire totem and remember all that you have learned in their attainment.\n\nNow, return to Tuluun.", sourceObjective = "Deliver Hauteur's Ashes to Tuluun at Azure Watch on Azuremyst Isle.", progress = "You look a bit singed around the edges.  How fared your communion with the flame, {class}?", completion = "You have passed through the cleansing fire of destruction and been renewed, {name}.  This is not unlike the tribulation the {race} people are currently undergoing.  And through saving Hauteur from himself, you have secured your connection to the elemental fire of this world.", sourceObjectiveStatus = "unverified-source-field" }
quests[9469] = { id = 9469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Featherbeard's Endorsement", description = "When I am finally granted an audience with Falstad Wildhammer, I hope to have our strongest advocate among the Wildhammer dwarves at my side, {name}.\n\nFeatherbeard is revered among his people, both for his legendary gryphon training skills and for his wisdom. If anyone can sway Falstad Wildhammer, it is he.\n\nI would go to see him myself, except that I cannot leave the confines of Aerie Peak while awaiting my audience. Visit Featherbeard at his residence to the south and ask if he will speak with me.", sourceObjective = "Go to Featherbeard's Hovel and visit the dwarf if he is at home. If he is not at home, search for evidence of where he can be found.", completion = "Featherbeard's journal appears to have a large number of recent entries. Leafing back to the beginning of the latest ones, you begin searching for clues about where he might have gone.", sourceObjectiveStatus = "unverified-source-field" }
quests[9470] = { id = 9470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gesture of Goodwill", description = "The rugged terrain of the Hinterlands is not only home to the Wildhammer dwarves and their gryphons, but also to a number of forest troll tribes.\n\nThe trolls view the Wildhammers as squatters on their ancestral lands and spare no opportunity to accost the dwarves by attacking the gryphon aeries. One way to prove ourselves in the eyes of the Wildhammer is to help staunch these attacks by killing a Witherbark leader, Witch Doctor Mai'jin, who shelters in a cave at Bogen's Ledge, to the west of Shadra'Alor.", sourceObjective = "Ambassador Rualeth at Aerie Peak wants you to slay Witch Doctor Mai'jin and his pet spider Tcha'kaz.", completion = "Well done, {name}. The Wildhammers will be heartened to know that they don't stand against the Witherbark trolls alone. Showing them that the Alliance can prove a reliable partner in protecting the gryphons should lend more weight to our proposition.", sourceObjectiveStatus = "unverified-source-field" }
quests[9471] = { id = 9471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preying on the Predators", description = "The Wildhammer dwarves act as companions, caretakers, and trainers to the gryphons. The gryphons have no shortage of enemies, especially among the forest troll tribes.\n\nSometimes, though, the threat comes from natural predators, such as wolves. A single animal is no match for a gryphon, but packs have taken to targeting gryphons more often because normal prey is scarce. Culling the wolves can help to reduce their impact on the gryphons and ingratiate us to the Wildhammer.", sourceObjective = "Ambassador Rualeth at Aerie Peak wants you to kill 10 Mangy Silvermane and 5 Silvermane Wolves.", completion = "<Ambassador Rualeth nods as you give your report.>\n\nYou have done well. The culling of the silvermane will not go unnoticed by the Wildhammer. When I meet with their leaders, I am certain that your deeds will reflect well upon the Alliance. Please accept this coin as a small token of my thanks, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9472] = { id = 9472, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arelion's Mistress", description = "With all the important matters at hand Arelion still found time in his schedule to see a mistress!\n\nIt's all becoming perfectly clear.  Viera Sunwhisper, that filthy wench... we'll show her to never cross a magistrix again.\n\nTake this scroll and find Viera.  Find a way to lure her away from town and use the scroll on her.\n\nArelion mentioned she couldn't resist a particular wine harvested by the cenarion druids.  You might find some at Cenarion Refuge, just inside Zangarmarsh, west of here.", sourceObjective = "Magistrix Carinda at Falcon Watch wants you to lure Viera Sunwhisper away from the settlement and then use Carinda's Scroll of Retribution on her.", progress = "Well, {name}.  Is it done?", completion = "Excellent!  That little backstabber won't be running off with anyone's husband any time soon.\n\nHere's a little something for your troubles.  I trust we can keep this incident between us, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9473] = { id = 9473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Alternative Alternative", description = "The girl is too far gone for mere ointments to be effective. There may be another way...\n\nThe forest of Azuremyst holds many secrets, one of those being a rare plant known as the azure snapdragon that some claim to be a panacea - a cure all.\n\nYou can identify the plant by its stark contrast to the other plants of Azuremyst and its need to grow at the base of the azure pine trees. Make haste!\n\nAnd {name}, be wary of the root threshers of the region as they consume snapdragon for sustenance.", sourceObjective = "Daedal at Azure Watch wants you to bring him 5 Azure Snapdragon Bulbs.", progress = "Do not waste time, boy.", completion = "Watch as the plant works its magic.", sourceObjectiveStatus = "unverified-source-field" }
quests[9474] = { id = 9474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mark of the Lightbringer", description = "In the short time that I have been on Azeroth I have studied many of its heroes.  Of them all, Uther Lightbringer stands above the rest.  A hero for the ages, in the end Uther was betrayed by his most promising pupil, Arthas.\n\nIn his honor, I would like to return something he lost to his nearby tomb.  It is rumored that the Scarlet Crusade is keeping one of his holy relics atop their guard tower near the gates of Hearthglen.\n\nPlease, {class}, go and retrieve it.", sourceObjective = "Obtain the Mark of the Lightbringer and return it to Anchorite Truuen at Chillwind Camp in the Western Plaguelands.", progress = "The Mark of the Lightbringer is a powerful symbol of Uther's faith in the Light.", completion = "Thank you, {class}!  The recovery of this holy symbol means a great deal to myself and others that honor the memory of Uther Lightbringer.", sourceObjectiveStatus = "unverified-source-field" }
quests[9475] = { id = 9475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaiming the Eggs", description = "Looking over the remains, you surmise that this broken and battered skeleton must be all that is left of Featherbeard. Clutched in one skeletal hand is a torn and stained sheaf of paper. You gently remove and unroll it, revealing a hand-drawn map and a few hastily scrawled notes.\n\nThe map appears to be a rendering of Shadra'Alor and its three temples with 'x' marks in several places, presumably the locations of the stolen eggs. You place the map in your pack for inspection at a safer location.", sourceObjective = "Gather 5 Gryphon Eggs and return them to Ambassador Rualeth at Aerie Peak.", progress = "The look on your face marks you as the bearer of bad news. What have you discovered?", completion = "<Handing the eggs to the ambassador, you describe the findings at Featherbeard's Hovel and Shadra'Alor.>\n\nThe Witherbark killed Featherbeard?\n\n<Rualeth's face contorts in horror at your description of the dwarf's death and the implications for Rualeth's mission.>\n\nI understand why he felt he had to go in search of the eggs, but I wish he'd thought to bring others along. His death will no doubt enrage Falstad Wildhammer, triggering retaliation against the trolls, and delaying my audience indefinitely.", sourceObjectiveStatus = "unverified-source-field" }
quests[9476] = { id = 9476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Pursuit of Featherbeard", description = "The journal's most recent entries detail Featherbeard's concern about a growing number of Witherbark troll raids on the Wildhammer gryphon aeries and a rash of egg thefts. A search of the smaller Witherbark settlements in the area appears to have yielded no information.\n\nThe last entry describes Featherbeard's suspicion that a Witherbark witch doctor named Mai'jin is behind the raids. The last, hastily written sentence states the dwarf's intention to travel to Shadra'Alor in search of the eggs.", sourceObjective = "Travel to Shadra'Alor and search for traces of Featherbeard.", completion = "Upon the altar is a heap of bones that appear to have belonged to a dwarven male. No identifying features remain, but you decide to search the body for confirmation that these are the remains of Featherbeard.", sourceObjectiveStatus = "unverified-source-field" }
quests[9483] = { id = 9483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Life's Finer Pleasures", progress = "Just because we're on this pilgrimage doesn't mean we have to give up all of life's pleasures.  It's been ages since I had a good wine.\n\nI'd literally kill for a bottle of cenarion spirits!\n\nI know, I know, how unfashionable of me to enjoy a drink brewed by night elves.", completion = "You know, maybe we can become friends after all.  Follow me; we don't want to have to share this with the others now, do we?" }
quests[9484] = { id = 9484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taming the Beast", description = "You have undoubtedly hunted and slain beasts for both your defense and sustenance, yet to befriend them and harness their strengths is only now within your grasp.  This I can teach you.\n\nTake this magical taming rod that allows a wild animal to temporarily bond and fight beside you.  Begin with the crazed dragonhawk, a nearly docile bird found just outside of Farstrider Retreat.  Return to me when this is done.", sourceObjective = "Use the Taming Rod to tame a Crazed Dragonhawk, and then return to Lieutenant Dawnrunner.", progress = "Have you mastered the dragonhawk?", completion = "Withstanding the numerous claws and bites from the dragonhawk is a sign of your tenacity.  Do you have the strength to learn more?", sourceObjectiveStatus = "unverified-source-field" }
quests[9485] = { id = 9485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taming the Beast", description = "You have done well, {name}.  Your understanding of the wild grows quickly.\n\nThe mistbat is a clever hunter, combining the swiftness of the dragonhawk and the ferocity of the springpaw.  Mistbats are found just across the Elrendar River to the south, preying on hapless travelers who wander into the Ghostlands.\n\nUse this final taming rod to befriend a mistbat and return to me when you have finished.", sourceObjective = "Use the Taming Rod to tame a Mistbat, and then return to Lieutenant Dawnrunner.", progress = "Have you mastered the mistbat?", completion = "So you see {name}, there is nothing left for me to teach you at this time.  You already understand what it is to befriend those you once hunted.  You need only to choose one of nature's allies with traits that match your own.", sourceObjectiveStatus = "unverified-source-field" }
quests[9486] = { id = 9486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taming the Beast", description = "The elder springpaw is an efficient and swift hunter.  In attempting to befriend one, it sees you as prey.  Do not be dissuaded.\n\nUse the taming rod to bring the great cat to your side and hunt beside it.  They are found throughout Eversong Woods, some very close to the lodge.  When you have learned enough, return to me.", sourceObjective = "Use the Taming Rod to tame an Elder Springpaw, then return to Lieutenant Dawnrunner.", progress = "Have you hunted alongside the springpaw?", completion = "You have shown both strength and tenacity.  There remains the final test until you can tame without the use of magic.", sourceObjectiveStatus = "unverified-source-field" }
quests[9487] = { id = 9487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Reavers", description = "Arcane reavers are magical creations of brute strength.  They are heavily armored and deliver stunning blows.  You, however, can bypass their defenses and avoid their attacks.  Your spellcraft is not without many advantages, {name}.\n\nTravel to Dawnstar Spire and blast apart the arcane reavers.  From their remains, collect the crystallized fragments of magical energy and return to me.  Dawnstar Spire is found to the east, across the lake.", sourceObjective = "Arcanist Vandril wants you to collect 10 Arcane Fragments for him.", progress = "Didn't get too close to the brutes, I hope?", completion = "Such a waste, using magic to construct beings of physical strength.  I always thought that's why we allied with the lesser races, after all.\n\nYou were good to destroy them so we can use what remains for a more suitable purpose.", sourceObjectiveStatus = "unverified-source-field" }
quests[9488] = { id = 9488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Simple Robe", description = "The arcane fragments you collected will do nicely.\n\nNicely for what, you ask?  For making a splendid robe fit for a {class} like yourself!\n\nAll we need now is some linen cloth and a spindleweb silk gland.  You can find the silk gland from any spindleweb spider, preferably after killing them.", sourceObjective = "Arcanist Vandril wants you to bring him 15 Linen Cloth and a Spindleweb Silk Gland.", progress = "The robe cannot be completed without the necessary supplies.  But you knew that, didn't you?", completion = "You really don't need to know the intricacies of crafting a magical robe, {name}, you just need to know what to bring me.\n\nAnd let me be honest, you brought enough for several robes.  The profit I'll make should more than cover the costs to make your robe, and even enough to buy myself something nice.  Looks like the thanks belong to you!", sourceObjectiveStatus = "unverified-source-field" }
quests[9489] = { id = 9489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleansing the Scar", description = "{name}, it is good you are here.  The Scourge attack our city with such endless hate that I fear the morale of our guard is breaking.\n\nHurry to the Dead Scar just south of the city where Jaela and her rangers stand ready.  Fill them with the power of the Light through your blessings.", sourceObjective = "Cast Power Word: Fortitude on 6 Eversong Rangers in the Dead Scar.", completion = "Already the rangers speak of your blessings with awe and respect.  Now you can see how the Light serves us, allowing us to help others, but only after we have helped ourselves.", sourceObjectiveStatus = "unverified-source-field" }
quests[9490] = { id = 9490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rock Flayer Matriarch", description = "Rock flayers are mean, nasty, violent creatures.  But the plain ones are like tame beasts when compared to their matriarch, Blacktalon the Savage.\n\nMy cousin got eaten by her and it wasn't pretty.  I swore that one day Blacktalon would pay for that.  You bring back proof of that monster's death and I will give you my life's savings.  Deal?\n\nYou're going to need some friends to kill Blacktalon.  Big tough friends with sharp swords.  You'll find her inside a cave in the Great Fissure.  Good luck!", sourceObjective = "Obtain Blacktalon's Claws from Blacktalon the Savage at the Great Fissure and bring it to Ikan at the Temple of Telhamat in Hellfire Peninsula.", progress = "Did you bring back proof of Blacktalon's death, {name}?", completion = "Yes, I remember these sharp claws!\n\nTake this reward, {name}.  That was a dangerous task you just did.  You deserve every bit of this reward.", sourceObjectiveStatus = "unverified-source-field" }
quests[9491] = { id = 9491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greed", description = "A rich, and I mean filthy rich, merchant came through here yesterday talking about some ring of \"immense archeological importance\" locked in one of the countless burial chests found in the Amani Catacombs.  When he wasn't talking about the ring, he was talking about how much he'd pay for it.\n\nTell you what, I'll front the thieves' tools, and if you manage to bring the ring back, I'll pay you enough to buy ten rings of your own!", sourceObjective = "Eralan in Tranquillien wants you to retrieve the Pitted Gold Band from the Amani Catacombs.", progress = "Please tell me you found the ring.  It won't be long before that merchant finds his own {class}.", completion = "This is the ring, is it?  Not much to look at, but you know what they say about one elves' trash...\n\nAnd let's not forget your payment.  Don't feel shy about spending it right here sweetie!", sourceObjectiveStatus = "unverified-source-field" }
quests[9492] = { id = 9492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turning the Tide", description = "The permanence of the orcish threat is one of the sad truths of Outland. There was a time when we Sons of Lothar believed we'd purchased Honor Hold's safety with our blood, but there was to be no peace.\n\nThe Sons will yield to no orc - green, brown, and now red - we will overcome them or die trying. If we are to have any expectation of victory, we must take the fight to them in Hellfire Citadel. Bring me the weapon of their self-styled 'Warchief' Kargath Bladefist and you will be well rewarded.", sourceObjective = "Bring Warchief Kargath's Fist to Force Commander Danath Trollbane in Honor Hold.", progress = "Have you returned with proof of 'Warchief' Kargath Bladefist's demise?", completion = "Well done, {name}. With your victory in Hellfire Citadel, we have struck a major blow against the orcs.\n\nI must speak with Field Commander Romus about following up and ensuring that the orcs stay on the defensive. Now that we've been reinforced, we can do far more than simply defend Honor Hold.", sourceObjectiveStatus = "unverified-source-field" }
quests[9493] = { id = 9493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pride of the Fel Horde", description = "We know precious little about the Fel Horde presence in Hellfire Citadel and our information has come at the cost of many lives.\n\nFel Horde troops under the command of Kargath Bladefist are a brutal, battle-hardened lot fortified by foul magics. The elite of this force, the Shattered Hand legionnaires, champions, and centurions are feared by the regulars and serve as an officer corps.\n\nTargeting and eliminating them is a necessary first step in any successful assault on the Fel Horde's leadership.", sourceObjective = "Field Commander Romus at Honor Hold wants you to kill 8 Shattered Hand Legionnaires, 4 Shattered Hand Centurions, and 4 Shattered Hand Champions.", progress = "I am not so naive as to think that the defeat of the Shattered Hand legionnaires heralds our victory over the Fel Horde, but is a good first step.", completion = "That is excellent news, indeed, {name}. With progress to report from Hellfire Citadel, perhaps we can afford to turn our attention to the Fel Horde presence other parts of the peninsula and Outland as a whole.", sourceObjectiveStatus = "unverified-source-field" }
quests[9494] = { id = 9494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fel Embers", description = "The stuffy academics of Azeroth have cowered in their towers for too long and it's fallen to me to show them what cutting edge research is! They're afraid to play with fire and that's exactly what I intend to do, once I get my hands on the fire, that is.\n\nWithin Hellfire Citadel's Shattered Halls, Grand Warlock Nethekurse performs unrivaled magical feats augmented by the powers of a pair of strange braziers. Using the vessel he uses to contain these fel embers, capture one and bring it back to me, {name}.", sourceObjective = "Magus Zabraxis at Honor Hold wants you to bring her a Fel Ember.", progress = "<Magus Zabraxis glances over at Amythiel Mistwalker and lowers her voice.>\n\nDid you bring the, err, ember?", completion = "Well done! I can't hope to replicate the feats of Grand Warlock Nethekurse, nor should I aspire to, but we would be fools to ignore the power of the fel embers.\n\nHowever, there are those who would forbid the type of research I'm about to embark upon, and for that reason, I must keep my efforts secret. Please do not speak of this to anyone, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9495] = { id = 9495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Will of the Warchief", description = "The struggle to free the orcish people from our tainted blood has not been easy, {name}. Warchief Thrall has seen too many orcish heroes laid low by fate's hand. Now, it seems Kargath Bladefist numbers among them.\n\nIn the Shattered Halls of Hellfire Citadel, Kargath has claimed the title of 'Warchief' of the Fel Horde. With an army of crazed, bloodthirsty fel orcs at his back, he won't rest until Thrallmar is destroyed. Warchief Thrall has commanded us to defeat Kargath and his forces at all costs.", sourceObjective = "Bring Warchief Kargath's Fist to Nazgrel in Thrallmar.", progress = "Have you proof of Kargath Bladefist's defeat?", completion = "You have done well, {name}. In his prime, Kargath Bladefist was a fine warrior, a hero and example to his people.\n\nHis death is a blow to us all, but especially to Warchief Thrall. Whatever happened to him in his final days, we should not forget the orc Kargath once was, nor the lessons to be learned from his downfall.\n\nFor your service to the Horde, {name}, you are to be rewarded with your choice from among these weapons.", sourceObjectiveStatus = "unverified-source-field" }
quests[9496] = { id = 9496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pride of the Fel Horde", description = "Overlord Maimfist's insults aside, {name}, this Fel Horde is nothing to be trifled with.\n\nFrom what we know, Fel Horde troops under the command of Kargath Bladefist are a brutal, battle-hardened lot fortified by foul magics. The elite of this force, the Shattered Hand legionnaires, champions, and centurions are feared by the Fel Horde regulars and serve as an officer corps.\n\nTargeting and eliminating them is a necessary first step in any successful assault on the Fel Horde's leadership.", sourceObjective = "Shadow Hunter Ty'jin at Thrallmar wants you to kill 8 Shattered Hand Legionnaires, 4 Shattered Hand Centurions, and 4 Shattered Hand Champions.", progress = "Once the Shattered Hand legionnaires have been broken, we can begin to make progress in our campaign against the Fel Horde. Have you carried out your mission, {name}?", completion = "Excellent job, {name}. With the legionnaires broken, it will be easier to face the Fel Horde on the battlefield, though they remain a formidable enemy.", sourceObjectiveStatus = "unverified-source-field" }
quests[9497] = { id = 9497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emblem of the Fel Horde", description = "When word of the so-called 'Fel Horde' reached the Warchief's ears, he was both furious and greatly saddened. Like Rend's pretenders before them, this false Horde too will fall, and its banner will adorn the wall of Grommash Hold as a testament to the Warchief's might.\n\nIt falls to you to carry out the Warchief's will in this matter, {name}. It will not be an easy task, for the banner is guarded by a champion of this Fel Horde, known as Warbringer O'mrogg, and he will not yield his charge without a fight.You will be able to choose one of these rewards:", sourceObjective = "Slay Warbringer O'mrogg and capture the Fel Horde Banner, then return it to Overlord Hun Maimfist at Thrallmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[9498] = { id = 9498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falcon Watch", description = "My people recently finished building Falcon Watch, a base of operations in the southwestern region of Hellfire Peninsula - beyond Hellfire Citadel.  You are welcome there as an ally, {name}.\n\nIf you're looking for work, go there and tell Ranger Captain Venn'ren that I sent you.  He will see to it that you're given tasks worthy of someone of your caliber.", sourceObjective = "Report to Ranger Captain Venn'ren at Falcon Watch in Hellfire Peninsula.", completion = "Welcome to Falcon Watch, {race}.  All our Horde allies are welcome here, especially those recommended by Martik.", sourceObjectiveStatus = "unverified-source-field" }
quests[9499] = { id = 9499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falcon Watch", description = "What are you still doing here, {name}?  Didn't you hear we built a proper sin'dorei outpost here in Hellfire Peninsula?\n\nSurely you'd rather be among fellow blood elves and away from all this... smell.  You'll find Falcon Watch in the southwest, beyond Hellfire Citadel.  Report to Ranger Captain Venn'ren; he will take care of you.\n\nThe road ahead is dangerous and heavily patrolled by Alliance scouts.  I would recommend travelling with companions.  Blood elves, preferably.", sourceObjective = "Travel to Falcon Watch in the southwest of Hellfire Peninsula and report to Ranger Captain Venn'ren.", completion = "Welcome to Falcon Watch, brother.  Many other blood elves haven't been fortunate enough to make it this far.\n\nIt's a terrible shame; our work in Outland has just begun.", sourceObjectiveStatus = "unverified-source-field" }
quests[9500] = { id = 9500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Water", description = "It's been a while since last you were tested.  Farseer Nobundo has been asking for you.  You must have grown greatly in wisdom because you are being called to learn the mysteries of the element of water.\n\nYou remember where to find him at the Crystal Hall inside of the Exodar, right?", sourceObjective = "Speak with Farseer Nobundo at the Crystal Hall inside the Exodar on Azuremyst Isle.", completion = "We meet again.  I have been watching your progress from afar, {class}, and I am pleased.\n\nThe time has come for you to commune with the element of water, to learn its mysteries and give yourself over to the water so that you might in turn learn to master it.", sourceObjectiveStatus = "unverified-source-field" }
quests[9501] = { id = 9501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Water", description = "A powerful water elemental named Aqueous has requested your presence.  It would seem that there is a great imbalance occurring in the water element on Bloodmyst Isle.  Not surprising given the unnatural predilections of the blood elves.\n\nYou will find Aqueous in a hidden reef under the waves off the northern shore of Bloodmyst Isle.\n\nTake this potion; it can help you to get to her once you get into the water near the reef.", sourceObjective = "Speak with Aqueous in the Hidden Reef at Bloodmyst Isle.\n\nProvided item:", completion = "Do not fear, {name}.  While you are here we will speak using our minds.\n\nI am grateful to Farseer Nobundo for sending you to me.  There is a great disturbance that is polluting the waters on and around Bloodmyst Isle.  Not even the blind would fail to notice the effect this is having on its creatures and the environment.\n\nYou and I will work together to stop this corruption before it spreads further.", sourceObjectiveStatus = "unverified-source-field" }
quests[9502] = { id = 9502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Water", description = "It's been a while since last you were tested.  Farseer Nobundo has been asking for you.  You must have grown greatly in wisdom because you are being called to learn the mysteries of the element of water.\n\nYou remember where to find him at the Crystal Hall inside of the Exodar, right?", sourceObjective = "Speak with Farseer Nobundo at the Crystal Hall inside the Exodar on Azuremyst Isle.", completion = "We meet again.  I have been watching your progress from afar, {class}, and I am pleased.\n\nThe time has come for you to commune with the element of water, to learn its mysteries and give yourself over to the water so that you might in turn learn to master it.", sourceObjectiveStatus = "unverified-source-field" }
quests[9503] = { id = 9503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Water", description = "In balance with the other elements, water is the source and sustenance of all living things.  It gives and nurtures life, and all rely upon it for their existence.  Yet, when polluted, it also brings life to an end.\n\nWe must determine the extent of the damage that has been done.  To the southwest is one such contaminated body of water that has come to be known as the Foul Pool.  Travel there and extract the foul essence from the water spirits that inhabit the pool.", sourceObjective = "Collect 6 Foul Essences and return them to Aqueous in the Hidden Reef at Bloodmyst Isle.", progress = "Have you collected the foul essences of my unfortunate sisters so soon, {name}?", completion = "Thank you, {class}.  These should be enough so that I can examine this corruption.  Then we will have a better idea of how to proceed.", sourceObjectiveStatus = "unverified-source-field" }
quests[9504] = { id = 9504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Water", description = "It is worse than I feared. The corruption is very potent and if unchecked it could spread to the ocean currents and be carried throughout all of Azeroth!\n\nWe are going to need a sample of the purest water to counter this malignancy. There are ruins on the untainted portion of this island, to the southeast. Go there, where the Wrathscale naga reside, and take from their fountain.\n\nUse this bota bag to gather the sample. Hurry, {name}!", sourceObjective = "Fill the Empty Bota Bag and then return to Aqueous in the Hidden Reef at Bloodmyst Isle.", progress = "You have the pure water from the ruins?", completion = "Water parts easily, yet put enough of it together and it will create an unstoppable force.  It washes away earth and fire, and easily pushes air out of the way.\n\nWe are that unstoppable force, {name}, not those that have poisoned Bloodmyst Isle!", sourceObjectiveStatus = "unverified-source-field" }
quests[9505] = { id = 9505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Prophecy of Velen", description = "The Prophet spoke of this day: That on this island, in this new world, our allies would find us.\n\n\"We will be tested. They will ask that we pay for the sins of our fathers...\"\n\nAt the time, I did not understand the meaning behind his words, but seeing this creature and her reaction to us, it is now coming into focus. The corruption of our people has been felt even here.\n\nVenture south. It is there that we found this being. Find its kin and tell them of our people.", sourceObjective = "Daedal wants you to travel south and seek out the people that the injured creature mentioned.", completion = "You say that you've found one of our crew and that she is injured? I will send one of my crewmen to your village immediately!", sourceObjectiveStatus = "unverified-source-field" }
quests[9506] = { id = 9506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Small Start", description = "I am Admiral Odesyus of Alliance Naval Command. Our ship was forced to port on your island due to an infestation of sorts. It's embarrassing to even talk about, but goblins somehow managed to stow away in the holds of both of my ships.\n\nLast night, while most of the ship's crew was asleep below deck, they struck!\n\nStranger still, they took our navigation gear and jumped ship!\n\nThey disappeared into the thicket, east of here. Will you go in search of our gear? It will make for a strong gesture.", sourceObjective = "Admiral Odesyus at Odesyus' Landing wants you to recover the Nautical Compass and Nautical Map stolen by the Venture Co.", progress = "Any luck, stranger?", completion = "You're a resourceful one! With our navigation gear, we can figure out just how far we've veered off course.\n\nBut wait, what's this? There's something rolled up in the map. Let me see...\n\nThese are orders from Mogul Razdunk of the Venture Company. According to these plans, they're here to strip-mine the island of the crystal wreckage, then hijack our ships once they're finished.\n\nBy Bronzebeard's bushy brow! This is why they forced us to land? How could they know of our plans?\n\nI smell a traitor...", sourceObjectiveStatus = "unverified-source-field" }
quests[9508] = { id = 9508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Water", description = "I have determined where the corruption is coming from.  It is the by-product of some demented research and you're going to put an end to it!\n\nJust to the southwest of the Foul Pool is a small camp.  There you will find the 'research' of Tel'athion the Impure.  This is where he produces the filth that has been seeping into the island's water.\n\nUse the pure water you obtained from Ashenvale to destroy his cache of barrels.  That will be sure to bring him out.\n\nWe will have an end to this!", sourceObjective = "Bring the Head of Tel'athion to Aqueous in the Hidden Reef at Bloodmyst Isle.", progress = "Have you succeeded?", completion = "It is done then!  The crisis is averted and you have put in motion the restoration of the water on Bloodmyst Isle.  Over time, the water, in conjunction with the other elements, will heal itself.\n\nIt is unfortunate that the blood elves cannot see that by contaminating their surroundings they're killing themselves off as well!", sourceObjectiveStatus = "unverified-source-field" }
quests[9509] = { id = 9509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Water", description = "I held back a little of the water from Ashenvale, not because I doubted your ability to deal with the situation.  Rather, I knew that you would succeed, and I wanted to make sure that you had something special to take back to Nobundo.\n\nHere, {name}, take this flask of pure water.  It will ensure that you receive a very powerful water totem.\n\nFarseer Nobundo awaits your return at the Exodar.", sourceObjective = "Take the Flask of Purest Water to Farseer Nobundo inside the Exodar on Azuremyst Isle.", progress = "The elements have spoken to me of the great deeds you have accomplished.  Come, let us speak.", completion = "You have comported yourself with wisdom beyond your years, {name}.  I can sense that the water element is pleased with your actions.  It will be my great honor to take the pure water that you bear and combine its essence into your new water totem.\n\nRemember well the lessons of water as you go forward and you will gain an even greater understanding and mastery of the element.", sourceObjectiveStatus = "unverified-source-field" }
quests[9510] = { id = 9510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bristlehide Clefthoof Hides", description = "So you're looking to make yourself useful?  We're in very short supply of clefthoof hides, {name}.\n\nIf you go southwest of here you'll find bristlehide clefthoof in abundance near a place called Falcon Watch.  Their hides are ideal for leatherworking.  Bring me a stack of them and I'll reward you appropriately.", sourceObjective = "Provisioner Braknar at Mag'har Post in Hellfire Peninsula wants you to bring him 5 Bristlehide Clefthoof Hides.", sourceObjectiveStatus = "unverified-source-field" }
quests[9511] = { id = 9511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kargath's Battle Plans", description = "<TXT>The documents you found on Kargath's body detail plans on what appears to be a massive invasion on Honor Hold." }
quests[9512] = { id = 9512, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cookie's Jumbo Gumbo", description = "The Admiral be right, ye are a resourceful one. Mayhap ye could help Cookie out?\n\nIf I serve the crew chicken for dinner again, I'll be sent to the brig fer sure.\n\nI noticed that thar be crawlers all along the coastline - lots o' crawlers! Bring me crawler meats and I'll be forever indebted to ya.\n\nHelp a reformed pirate out?", sourceObjective = "\"Cookie\" McWeaksauce at the Odesyus' Landing wants you to bring him 6 Skittering Crawler Meat.", progress = "Arrr... Yarr... Shiver me timbers... Er, sorry lad, I gotta practice me pirate lest I forget it...", completion = "Bless yer heart, stranger. This'll go a long ways in liftin' the morale o' the crew.", sourceObjectiveStatus = "unverified-source-field" }
quests[9513] = { id = 9513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaiming the Ruins", description = "While some may look at our current predicament as an unfortunate turn of events, I sense that we are here for a reason. The invisible hand of fate has pushed us in this direction. The reason why will become evident in time.\n\nTo the west lies an ancient night elf city, now in ruin and overrun with naga. It would be remiss of me to sit idly by as the naga tainted my ancestral lands.\n\nYou have shown yourself a capable {class}. Honor my people and cleanse the ruins of their unwelcome inhabitants.", sourceObjective = "Priestess Kyleen Il'dinare at Odesyus' Landing on Azuremyst Isle wants you to kill 5 Wrathscale Myrmidons, 5 Wrathscale Naga and 5 Wrathscale Sirens.", completion = "Elune be praised! The restless spirits may find tranquility after all.", sourceObjectiveStatus = "unverified-source-field" }
quests[9514] = { id = 9514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rune Covered Tablet", description = "You cannot make out any of the symbols on the tablet. Perhaps the priestess would be able to decipher the mysterious runes.", sourceObjective = "Take the Rune Covered Tablet to Priestess Kyleen Il'dinare at Odesyus' Landing on Azuremyst Isle.", progress = "You've found something?", completion = "I can't read these runes but I know someone who can...", sourceObjectiveStatus = "unverified-source-field" }
quests[9515] = { id = 9515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warlord Sriss'tiz", description = "A naga invasion would be disastrous, {name}. I've seen what naga can do and I would not want to see such a catastrophe befall any being. If I were to guess, this Warlord Sriss'tiz will be hidden in a cave - probably along the coast to the west.\n\nFind Warlord Sriss'tiz and put an end to his reign.", sourceObjective = "Priestess Kyleen Il'dinare at Odesyus' Landing on Azuremyst Isle wants you to kill Warlord Sriss'tiz.", completion = "With Warlord Sriss'tiz dead, the possibility of a naga invasion is now only a distant memory. We are safe, for the time being...\n\nI must admit, I was wrong to think badly of you, {name}. You have shown that you are nothing like the filth that was Archimonde. Accept this as a gift from the night elves.", sourceObjectiveStatus = "unverified-source-field" }
quests[9516] = { id = 9516, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destroy the Legion", description = "I will not tolerate their existence on this world!  The Burning Legion all but destroyed our race and we fell back to settle a new home on a new world.  Then they came again.  And we retreated, over and over.\n\nNo more!\n\nThere is a remnant of the Legion to the south in the regions known as Felfire Hill, Demon Fall Canyon and Demon Fall Ridge.  They are what is leftover from a force that once long ago invaded this world.\n\nGo and destroy as many as you can before it is too late!", sourceObjective = "Slay 6 Mannoroc Lashers, 6 Felguards and 6 Searing Infernals, and then return to Vindicator Vedaar at Forest Song in Ashenvale.", completion = "You have my respect and thanks, {class}.  Perhaps we'll be able to create a new home here without having to worry about the Burning Legion yet again.", sourceObjectiveStatus = "unverified-source-field" }
quests[9517] = { id = 9517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shameful Waste", description = "Welcome to Forest Song, {class}. Where you see tents, there will one day be buildings, but such ambitions require a steady stream of building materials. I cannot bring myself to order our workers to fell any of the ancient trees of this grove, but our neighbors to the south and west have no such reverence for the forest.\n\nWe shall relieve the Warsong loggers of their excess, and reclaim some of the tainted wood from the satyr stronghold to the west. Bring the wood to Gnarl, who will purify it for our use.", sourceObjective = "Bring 15 pieces of Warsong Lumber and 5 Satyrnaar Fel Wood to Gnarl at Forest Song.", progress = "<The ancient creaks as it turns toward you.>\n\nArchitect Nemos said that you might be bringing wood salvaged from the deforesters' encampment and befouled Satyrnaar.", completion = "Wood cut with orcs' crude blades is warped as surely as that exposed to elemental extremes. Nothing sound can be built with it, but I shall purify it and return it to Architect Nemos and his men for their use. Some good will come from this tragedy, after all.", sourceObjectiveStatus = "unverified-source-field" }
quests[9518] = { id = 9518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agents of Destruction", description = "The Warsong Lumber Camp is a blight upon an embattled landscape. Every time we make progress in halting their operations, Overseer Gorthak orders his loggers to redouble their efforts!\n\nNow, the orcs are cutting more wood than they can possibly use, leaving it to rot while their blades bite into fresh trees! This is an affront to all we stand for, {name}, and we will show them that we'll not suffer further destruction of our lands!\n\nGo, and do not rest until Overseer Gorthak and his minions are dead!", sourceObjective = "Sentinel Luciel Starwhisper at Forest Song wants you to kill Overseer Gorthak, 2 Warsong Shredders, 5 Horde Deforesters, and 10 Horde Scouts.", progress = "As long as Overseer Gorthak lives, I will oppose him. What news from the lumber camp?", completion = "At last we have sent a message that the orcs won't dare ignore. Any overseer or foreman who sets foot within the camp to replace Gorthak will feel my wrath!\n\nWe must press our advantage, {name}, and never rest until the Warsong Lumber Camp is a distant memory and a glade of trees stands upon that ground.", sourceObjectiveStatus = "unverified-source-field" }
quests[9519] = { id = 9519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Chalice", description = "The area to our west, now called Satyrnaar, was once a prominent shrine built by my people. It housed a priceless relic, the Chalice of Elune, entrusted to the shrine's keepers by the priests of Elune. Pilgrims once traveled to the shrine to experience the healing powers the chalice was rumored to hold.\n\nThese stories might be nothing but old wives' tales, but if there is any truth to them, the relic may hold the key to rejuvenating the wounded forest. I must know, {name}.", sourceObjective = "Bring the Chalice of Elune to Kayneth Stillwind at Forest Song.", progress = "Can you feel it, {name}, the touch of corruption upon the wind? If we do nothing, it will continue to advance. That is why I seek the Chalice of Elune. Were you able to find it?", completion = "Excellent work, {name}. There is certainly a latent power here, one that not even constant exposure to the corruption of the satyr can dim. Do you see how it still shines, after all these years?", sourceObjectiveStatus = "unverified-source-field" }
quests[9520] = { id = 9520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diabolical Plans", description = "The demon dropped this parchment, which is amazingly written in the Common tongue!  The ones mentioned in it, Diathorus and Gorgannon, are the two infamous dreadlords that control the demons hereabouts.\n\nThe plans detail preparations for a demonic attack on Forest Song to the north; the location where a new draenei settlement is being established.\n\nPerhaps Vindicator Vedaar at Forest Song would be interested in these?", sourceObjective = "Deliver the Diabolical Plans to Vindicator Vedaar at Forest Song in Ashenvale.", progress = "What do you have there, sir?", completion = "By the Seven Crystals of Ata'mal, this cannot be!  They plan to attack us here at Forest Song?!\n\nNot on my watch!\n\n<Vindicator Vedaar crumples the demon-scrawled plans in his fist.>\n\nNo.  We will not allow this to happen!", sourceObjectiveStatus = "unverified-source-field" }
quests[9521] = { id = 9521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report from the Northern Front", description = "The battle against the Warsong Lumber Camp isn't being waged from Forest Song alone, {name}. There's a more substantial Silverwing Sentinel presence at Silverwing Grove to the southwest, near the border with the Barrens. From the grove, Sentinel Farsong directs our efforts against those who would destroy our lands.\n\nI'm a bit late in sending my latest report to Sentinel Farsong, but also hesitant to leave Forest Song unattended. If your travels take you near Silverwing Grove, would you deliver my report?", sourceObjective = "Deliver Sentinel Luciel's report to Sentinel Farsong at Silverwing Grove.", progress = "What's that you have there, {class}?", completion = "Thank you for delivering this report, {class}. From what Sentinel Luciel writes, it seems our worst fears have come to pass. With each advance we make, the Horde appears more determined to do as much damage as possible.\n\nWe can't afford to back down; the fate of our ancestral lands hangs in the balance. With more people like you on the frontlines, I'm certain we could triumph. Will you join our fight?", sourceObjectiveStatus = "unverified-source-field" }
quests[9522] = { id = 9522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Never Again!", description = "{name}, it falls to you to see that this attack by the Burning Legion never comes to pass.  You must go and slay their leaders.  Without them the rest of the demons are essentially mindless.\n\nYou will find Gorgannon in Demon Fall Canyon south beyond Felfire Hill, near Mannoroth's floating, broken spear.\n\nDiathorus the Seeker resides somewhere in the barrow den atop Demon Fall Ridge.  To find the ridge, look for a ramp up from Demon Fall Canyon near the Horde's monument to Grom Hellscream.", sourceObjective = "Kill Gorgannon and Diathorus the Seeker, and then return to Vindicator Vedaar at Forest Song in Ashenvale.", completion = "Never again will the Burning Legion threaten us here!  You have delivered us from a fight we very likely would have lost, {class}.\n\nI give you thanks and the deepest gratitude of the Hand of Argus.  It honors me to have you at our side.", sourceObjectiveStatus = "unverified-source-field" }
quests[9523] = { id = 9523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Precious and Fragile Things Need Special Handling", description = "The priestess tells me that the ruins to the west are what's left of a night elf civilization. That got me thinking about what my pappy used to always say about night elf ruins, \"Sonny, whenever you see night elf ruins, night elf relics are sure to be close by.\"\n\nNow what kind of a dwarf would I be if I didn't hire the first person I saw to go digging up night elf relics for me? Now get going!", sourceObjective = "Archaeologist Adamant Ironheart at Odesyus' Landing on Azuremyst Isle wants you to bring him 8 Ancient Relics.", progress = "Don't come back without some ancient relics.", completion = "My pappy would be proud! His boy strikes it big at the first set of night elf ruins he comes across... With your help, of course. Yes, don't worry, I won't leave you out of the discovery. Your name is {name}, right? They'll learn all about you in Ironforge.", sourceObjectiveStatus = "unverified-source-field" }
quests[9524] = { id = 9524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imprisoned in the Citadel", description = "Alliance, here?!  Listen carefully, {class}.\n\nKargath has captured several of our soldiers.  Captain Alina, an important officer is among them.  You must try to save her before she is executed.\n\nDon't worry about me, I'll find a way out as soon as I catch my breath.", sourceObjective = "Rescue Captain Alina inside Hellfire Citadel before she is executed.\n\nThis quest must be completed in Heroic dungeon difficulty.", completion = "I thank you, {name}.  I must admit I didn't expect a rescue party to be on its way.\n\nI will round up the remaining prisoners and lead them back to Honor Hold.", sourceObjectiveStatus = "unverified-source-field" }
quests[9525] = { id = 9525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imprisoned in the Citadel", description = "I was fortunate to escape Kargath's prison today, {name}.  Several prisoners are scheduled to be executed, an important officer among them.\n\nIt would be a huge blow against our forces if Captain Boneshatter was slain.  You must do what you can to rescue him.  I'm too weak to go on...", sourceObjective = "Rescue Captain Boneshatter inside Hellfire Citadel before he is executed.\n\nThis quest must be completed in Heroic dungeon difficulty.", completion = "You've brightened my day, {class}.  When I die, I will make sure it's in the battlefield... covered in the blood of my opponents and taking them down with me.", sourceObjectiveStatus = "unverified-source-field" }
quests[9526] = { id = 9526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaiming Felfire Hill", description = "Little one, to the south is an area of Nightsong Woods that has in recent times come to be called Felfire Hill.  It is very sad to see the demons crawling over it, spreading their corruption.\n\nWould you do something to help take back the land?\n\nI have a number of seeds that I have been saving for such a purpose.  Take them to Felfire Hill and plant them in the fertile dirt mounds.", sourceObjective = "Plant 8 Tree Seedlings in the Fertile Dirt Mounds and then return to Gnarl at Forest Song in Ashenvale.", completion = "Good.  Though it may take a great deal of your years for the seedlings to grow into ancients, in the fullness of time they will aid us in our fight against the demons at Felfire Hill.\n\nGo in peace, little brother.", sourceObjectiveStatus = "unverified-source-field" }
quests[9527] = { id = 9527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All That Remains", description = "We had lived peacefully among the Owlbeasts of this island for many years. You can imagine my surprise when they stormed the beach and attacked us.\n\nI fought tooth and nail but was easily overpowered. As I blacked out from the vicious blows that I had been dealt, I prayed that my family not suffer.\n\nWhen I awoke, all was quiet. The sand was soaked red with blood - their blood. They were devoured whole.\n\nI care not for vengeance, {name}. I only ask that their remains be returned to me for proper burial.", sourceObjective = "Cowlen on Azuremyst Isle wants you to recover the Remains of Cowlen's Family.", progress = "My wife was named Thalrisa and my daughter, Magwin.", completion = "Thank you, {name}. Their spirits will be at peace now.", sourceObjectiveStatus = "unverified-source-field" }
quests[9528] = { id = 9528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Cry For Help", description = "My family was attacked by the murlocs and owlkin of this island several weeks ago. I managed to escape but I think that both my mother and father have been slain. I don't know what I'm going to do now, but I must try and get back to my home - or what's left of it... Will you help me get through the forest?", sourceObjective = "Escort Magwin through the island to her home.", progress = "Hail, {name}.", completion = "<Tears of joy stream down Cowlen's face.>\n\nHow can I ever repay you for this, {name}? Please, take this heirloom. It symbolizes a sacred bond of friendship, trust and love amongst night elves. You are a brother to me - from this day until the end of time...", sourceObjectiveStatus = "unverified-source-field" }
quests[9529] = { id = 9529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stone", description = "While I'm certain your imp has proven a useful and sometimes entertaining servant, it is time you mastered a more powerful demon: the voidwalker.\n\nTravel down the Dead Scar until it is crossed by the Elrendar River.  Just south of the river, locate one of the blue glowing stones and take it.  Your path will be revealed there.", sourceObjective = "Obtain a Voidstone from the Dead Scar.", completion = "As you gaze into the stone, your vision begins to swirl...", sourceObjectiveStatus = "unverified-source-field" }
quests[9530] = { id = 9530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I've Got a Plant", description = "I've wondered about this for some time now, but this proves it to be true.\n\nThere is a traitor among us.\n\nThe plans left behind by the goblins document the conspiracy. Since I don't know who it could be, I'm going to need your help in finding the traitor. None of my crew can be trusted.\n\nIf this is going to work, I'm going to need a hollowed out tree and leaves. Search near the loggers north of us for the tree. You'll need to find the leaves by yourself. Check the forest.", sourceObjective = "Admiral Odesyus at Odesyus' Landing on Azuremyst Isle wants you to bring him a Hollowed Out Tree and 5 Piles of Leaves.", progress = "I love it when a plan comes together...", completion = "I must warn you, what I ask of you next will be dangerous. I won't think less of you if you decide not to help me out, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9531] = { id = 9531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tree's Company", description = "According to the plans, the traitor and the leader of the goblins, Geezle, are to meet at a cove on the western island. I need you to be at that meeting, {name}.\n\nRemember the tree and leaves? You're going to wear them! It's a perfect disguise.\n\nGo to the cove and look for a naga flag. If the flag is there, it means a meeting is planned. Use the disguise kit when you see the flag and wait. Eventually the traitor will show up. Let the meeting finish then return to me with the identity of the scoundrel.", sourceObjective = "Admiral Odesyus at Odesyus' Landing on Azuremyst Isle wants you to observe the meeting that is to take place between Geezle and the traitor.\n\nReturn to him when you know the identity of the traitor.", progress = "That traitor is going to wish he never messed with Alliance Naval Command!", completion = "I can't believe it! It was the gnome all along... I should have known!", sourceObjectiveStatus = "unverified-source-field" }
quests[9532] = { id = 9532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find Keltus Darkleaf", description = "{name}, one of our scouts has taken too strong an interest in his duties.  He surveys our enemies relentlessly, but sends no reports of his findings.\n\nYou must find this spy, Keltus Darkleaf, convince him to hand over his report and return it to me as swiftly as possible.  He can be found far to the southwest, where the Elrendar River forks and flows around Goldenmist Village.  The night elves of An'daroth are his quarry, and he won't be far from them.", sourceObjective = "Locate Keltus Darkleaf.", completion = "I hope you can see I am deep under cover... at least I was.", sourceObjectiveStatus = "unverified-source-field" }
quests[9533] = { id = 9533, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Helping Hand", description = "My people have undertaken an important endeavor in the eastern part of Ashenvale, with support and cooperation from the kaldorei.\n\nUnder the supervision of Architect Nemos and Vindicator Vedaar, they are revitalizing an old night elf outpost. The task of building won't be easy, {name}, for the challenges and enemies they face are many. I know Architect Nemos and his compatriots at Forest Song would appreciate any help they can get, and he has asked me to send any interested <men/women> his way.", sourceObjective = "Make your way to Forest Song and speak with Architect Nemos.", completion = "It's good to see another new arrival here at Forest Song.\n\nVindicator Palanaar is sending as much help as she can muster and each set of hands is appreciated.\n\nTake a look around, {class}. It may not be much now, but with time and help from our night elf allies, we'll build a settlement worthy of calling home. There is much to be done here and any help you can provide would be welcome.", sourceObjectiveStatus = "unverified-source-field" }
quests[9534] = { id = 9534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destroy the Legion", description = "The remains of the demonic Burning Legion have been making raids against our Warsong Lumber Camp!\n\nNo more!\n\nThe demons are attacking from the areas known as Felfire Hill, Demon Fall Canyon and Demon Fall Ridge to the east.\n\nGo and destroy as many as you can to bring glory to both yourself and the Horde!", sourceObjective = "Slay 6 Mannoroc Lashers, 6 Felguards and 6 Searing Infernals, and then return to Valusha at Splintertree Post in Ashenvale.", progress = "Are there not demons yet standing?  You call yourself a {race}?  This is no time to be taking a break from the fighting!", completion = "That's better!  There's nothing quite like ridding our world of a demon.  And they make for worthy opponents as well, unlike the weak races of the Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[9535] = { id = 9535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diabolical Plans", description = "The demon dropped this parchment, which is amazingly written in the Orcish tongue!  The ones mentioned in it, Diathorus and Gorgannon, are the two infamous dreadlords that control the demons hereabouts.\n\nThe plans detail preparations for a demonic attack on Splintertree Post to the northwest.\n\nYou're certain that Valusha at Splintertree Post would be interested in these.", sourceObjective = "Deliver the Diabolical Plans to Valusha at Splintertree Post in Ashenvale.", progress = "What do you have there, scout?", completion = "Dreadlords!  They plan to attack us here at Splintertree Post?!\n\nNot while I still draw breath!\n\n<Valusha crumples the demon-scrawled plans in her fist.>\n\nNo.  We will not allow this to happen!  They are a blight upon our world!", sourceObjectiveStatus = "unverified-source-field" }
quests[9536] = { id = 9536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Never Again!", description = "{name}, you will see to it that this attack by the Burning Legion never comes to pass!  Go and slay these dreadlords!  Without them the rest of the demons are essentially mindless.\n\nYou will find Gorgannon in Demon Fall Canyon south beyond Felfire Hill, near Mannoroth's floating, broken spear.\n\nDiathorus the Seeker resides somewhere in the barrow den atop Demon Fall Ridge.  To find the ridge, look for a ramp up from Demon Fall Canyon near the monument to Grom Hellscream.", sourceObjective = "Kill Gorgannon and Diathorus the Seeker.", progress = "Those dreadlords must die soon, {name}!", completion = "Never again will the Burning Legion make slaves of the orcs, or any other race of the Horde!\n\nBravely fought, {class}!  You have the true heart of the Horde beating inside of you!  You give us much honor!", sourceObjectiveStatus = "unverified-source-field" }
quests[9537] = { id = 9537, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Show Gnomercy", description = "Spark must be brought to justice!\n\nI need you to go down to the beach and find that deceitful gnome. Once you find him, get whatever information you can out of him!\n\nIf a high ranking official of the Alliance has committed treasonous acts, who knows how many others are corrupt?\n\nAnd {name}, use force if you have to...", sourceObjective = "Admiral Odesyus at Odesyus' Landing wants you to recover the Traitor's Communication from Engineer \"Spark\" Overgrind.", progress = "Did you find the lying dog?", completion = "Incredible! This was all part of their master plan!\n\nThis information must reach the king and your own leaders. The implications are staggering.", sourceObjectiveStatus = "unverified-source-field" }
quests[9538] = { id = 9538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning the Language", description = "I think I've cracked it, {name}!\n\n<Aurren points to the totem.>\n\nAll that we need to know about the Stillpine furbolg language is imprinted on their totems. With just a rudimentary understanding of how their symbols work, we can study the totems and learn to communicate with the furbolgs.\n\nI've written down the basics of the symbol matrix on this parchment. Study it and then examine the totem. It should lead you to the next language totem.\n\nSpeak to Arugoo when you return an educated {race}!", sourceObjective = "Read the Stillpine Furbolg Language Primer that Aurren gave you and interact with the Totem of Akida at Azure Watch.", progress = "You can hear a low-pitched hum emanating from the totem.", completion = "The totem has various primal markings. You see owls, bears, wolves and stags carved into the surface.\n\nYou note a strange collection of symbols that makes your mouth form the word A-K-I-D-A.", sourceObjectiveStatus = "unverified-source-field" }
quests[9539] = { id = 9539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totem of Coo", description = "You begin to read the totem, barely able to pronounce the awkward words and phrases. Slowly, words start to form in your head. You think that the totem is telling you to go up the nearby hill, to the northeast.", sourceObjective = "Find the Totem of Coo using the clues provided to you.", completion = "The totem has various primal markings. You see owls, bears, wolves and stags carved into the surface of the totem.\n\nYou note a strange collection of symbols that makes your mouth form the word C-O-O.", sourceObjectiveStatus = "unverified-source-field" }
quests[9540] = { id = 9540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totem of Tikti", description = "You begin to read the totem, better able to pronounce the words and phrases. Words start to form in your head. You think that the totem is telling you to go across the Crystalbrook river to the east. Perhaps your destination is on the other side of the river.", sourceObjective = "Find the Totem of Tikti using the clues provided to you.", completion = "The totem has various primal markings. You see owls, bears, wolves and stags carved into the surface of the totem.\n\nYou note a strange collection of symbols that makes your mouth form the word T-I-K-T-I.", sourceObjectiveStatus = "unverified-source-field" }
quests[9541] = { id = 9541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totem of Yor", description = "The symbols on this totem seem to translate much faster. The patterns and imagery all seem to blend into familiar words. You are fairly certain the totem is pointing you south, down the river. Something is at the bottom of the river itself.", sourceObjective = "Find the Totem of Yor using the clues provided to you.", completion = "The totem has various primal markings. You see owls, bears, wolves and stags carved into the surface of the totem.\n\nYou note a strange collection of symbols that makes your mouth form the word Y-O-R.", sourceObjectiveStatus = "unverified-source-field" }
quests[9542] = { id = 9542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totem of Vark", description = "You no longer see unrecognizable symbology in the totems. The totem of Yor reads to you just as easily as your native tongue.\n\nThe markings identify another furbolg den, due west of here. You are able to expertly decipher the language on the totem and know that your destination is Bristlelimb Village. Yor will guide you but if you get lost, you know that you are able to take the ancient elven road in the forest leading west to reach your destination.", sourceObjective = "Find the Totem of Vark using the clues provided to you.", completion = "As you read the totem, your mouth forms the word V-A-R-K. You understand this to mean justice.", sourceObjectiveStatus = "unverified-source-field" }
quests[9543] = { id = 9543, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atonement", description = "Our history with the orcs is one of constant conflict, {name}.  We were once near driven to extinction due to their bloodlust and have since then avoided them even when not under demonic influence.\n\nYet, this retaliation... it's not what Sedai would've wanted.  Speak with our elder, Amaan the Wise.  He will help shed light on these events.", sourceObjective = "Speak to Amaan the Wise at the Temple of Telhamat in Hellfire Peninsula.", completion = "Can I offer you any assistance, {name}?  You sound troubled.", sourceObjectiveStatus = "unverified-source-field" }
quests[9544] = { id = 9544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Prophecy of Akida", description = "The images on this totem depict a war between the Stillpine and the Bristlelimb furbolg tribes. The etchings show that the Bristlelimb have done unconscionable things to the furbolgs of Stillpine.\n\nAmidst the chaos, a prophecy has begun to unfold: A hero will rise - not of furbolg blood - and save the Stillpine tribe.\n\nSlay Bristlelimb furbolgs at Bristlelimb Village for their keys. Use the keys to free the Stillpine captives. Return to Arugoo of the Stillpine when you have freed them all!", sourceObjective = "Free 8 Stillpine Captives from cages found in Bristlelimb Village. Return to Arugoo of the Stillpine at Azure Watch when you have completed this task.", completion = "[Furbolg] The prophecy spoke of one that would rise and deliver us from the oppressive grasp of Bristlelimb -- that the spirits themselves would herald the arrival of this hero.\n\nAnd now, you have come.\n\nI humble myself before you, great one.", sourceObjectiveStatus = "unverified-source-field" }
quests[9545] = { id = 9545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Seer's Relic", description = "The stubborn close their mind and convince themselves of one truth.  The wise keep an open mind to the different possibilities leading to and stemming from the present.\n\nTake this relic with you to where you found Sedai.  See not with your eyes, {name}, but with your mind.", sourceObjective = "Amaan the Wise at the Temple of Telhamat in Hellfire Peninsula wants you to return to Sedai's Corpse, northeast of the Temple of Telhamat, and use the Seer's Relic at that location. Return to him after you've completed this task.", progress = "Have you seen the vision yet, {name}?", completion = "I hope the vision you witnessed helped you gain some perspective on Sedai's death.  The relic showed you a likely series of events leading up to the present.  The truth may have been different, we'll never know for sure.\n\nWould you act differently knowing what you know now?\n\nWho can say whether our conflict with the orcs will continue?  What's important is to remain open to the possibilities.", sourceObjectiveStatus = "unverified-source-field" }
quests[9547] = { id = 9547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Air", description = "{name}, Farseer Nobundo has been asking for you.  It must be time for you to learn the secrets of air, the last of the elements!\n\nI want you to know that I'm very proud of all that you have accomplished thus far.  I know that you have great things ahead of you.", sourceObjective = "Speak with Farseer Nobundo at the Crystal Hall inside the Exodar on Azuremyst Isle.{name}, Farseer Nobundo has been asking for you. It must be time for you to learn the secrets of air, the last of the elements!\n\nI want you to know that I'm very proud of all that you have accomplished thus far. I know that you have great things ahead of you.", sourceObjectiveStatus = "unverified-source-field" }
quests[9548] = { id = 9548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pilfered Equipment", description = "Shh! Keep your voice down and don't call attention to me.\n\nIf the murlocs detect my presence, the experiment will be ruined! I've already come perilously close to contaminating my data.\n\nWhile I was foraging yesterday, one of them must've wandered too close and discovered my camp. I returned just in time to see two of them carrying off a crate with most of my equipment! It's bound to be in one of their settlements around here, but I can't risk revealing my presence. Are you willing to help?", sourceObjective = "Bring Clopper's Equipment back to Clopper Wizbang, who is hiding in a beached turtle shell.", progress = "Did you manage to find my equipment?", completion = "This is fantastic! The theft of my equipment has given me more insight into the nature of these murlocs than I could have possibly gained in weeks of observations!\n\nI know what I'm going to say in my report already.\n\n'When faced with the products of a technologically superior culture, the Blacksilt displayed none of the curiosity characteristic of emerging cultures in humanoid species.'\n\nIt's brilliant! The gentlemen in Ironforge are going to love it! I can't thank you enough, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9549] = { id = 9549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artifacts of the Blacksilt", description = "My observations and writings about the Blacksilt murlocs are quite illuminating, {name}, but they are just the beginning. I plan to return to Ironforge with items produced by the Blacksilts' rudimentary crafting skills.\n\nThe problem is that the Blacksilt carry these items with them at all times, and I can't have their blood on my conscience. If you're willing to help me gather the idols carried by Blacksilt seers and crude knives of the Blacksilt warriors and shorestrikers, I won't ask how you came by them.", sourceObjective = "Bring 3 Crude Murloc Idols and 6 Crude Murloc Knives to Clopper Wizbang, who is hiding in a beached turtle shell.", progress = "Do you have those samples for me to send back to Ironforge?", completion = "Astounding, simply astounding! These are perfect, {name}. I can already see them under the glass in the museum in Ironforge. The text for the display is virtually writing itself in my head!\n\nYour help has been invaluable in getting my studies back on track. How do you spell your name? I'll make sure it appears in my report as co-author.\n\nOne of the chaps on the ship gave me this 'treasure map' to cover a gambling debt, but mythology isn't my area of study. Superstitious lot, sailors.", sourceObjectiveStatus = "unverified-source-field" }
quests[9550] = { id = 9550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Map to Where?", description = "The crudely-drawn map reveals nothing of its maker, but it appears to have been drawn with an unsteady hand. Wavering lines and symbols depict a small pavilion with broken columns located to the west of a partially submerged tower. \n\nIf the map is to be believed, this cluster of ruins appears to be located on the eastern coast of the island. You have no idea what you'll find, but it was important enough for the map's creator to record.", sourceObjective = "Locate the pavilion described by the map and search for what the map's maker was trying to record.", progress = "Perhaps this old journal is what the map is referencing.", completion = "Examining the book carefully, you conclude that it must be a journal. Its pages are filled with an elegant script differing from that of the map. The text of many of the pages is obscured by drawings and writing in the mapmaker's hand.\n\nIt's nearly impossible to make out the text beneath the mapmaker's tales of drunken carousing during shore leave.", sourceObjectiveStatus = "unverified-source-field" }
quests[9551] = { id = 9551, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Air", description = "{name}, Farseer Nobundo has been asking for you.  It must be time for you to learn the secrets of air, the last of the elements!\n\nI want you to know that I'm very proud of all that you have accomplished thus far.  I know that you have great things ahead of you.", sourceObjective = "Speak with Farseer Nobundo at the Crystal Hall inside the Exodar on Azuremyst Isle.", completion = "And finally we come to it, the last of the four great elements: air.  Do you think yourself wise enough to continue, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[9552] = { id = 9552, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Air", description = "The great spirit of air calls out to you, {name}, and it is time for you to take heed.\n\nI wish for you to travel up the Wildwind Path on the north facing of the mountain that the Exodar has crashed into.  At its peak you will find a cave and within will be one of my most accomplished pupils, Velaada.\n\nPlease, listen to her wisdom and do as she bids.  When you return you will have a greater understanding of the element of air.", sourceObjective = "Speak with Velaada at Wildwind Peak on Azuremyst Isle.", completion = "It was whispered to me on the winds that you would be coming, {class}.\n\nFarseer Nobundo thinks very highly of you, and from what I have heard of your travels, so do I.", sourceObjectiveStatus = "unverified-source-field" }
quests[9553] = { id = 9553, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Air", description = "While air may seem ethereal, it is an all pervasive force, covering and permeating everything around us.\n\nThough you cannot see it, the rocks of this cave are composed mostly of air, the waters of the oceans are saturated in it and without it, fire cannot be sustained.  Just don't let those elements hear you repeat that!\n\nWho you really wish to speak with for such wisdom is nearby.  At the northern edge of the precipice, Susurrus awaits you.  It is from him that you will gain understanding.", sourceObjective = "Speak with Susurrus at Wildwind Peak on Azuremyst Isle.", completion = "I have been awaiting your arrival, {class}.  You come seeking wisdom, and something else I sense.\n\nVery well, let us begin.", sourceObjectiveStatus = "unverified-source-field" }
quests[9554] = { id = 9554, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Air", description = "While my brothers and sisters of the other elements have demanded that you perform various tasks, I will not ask anything further of you.  I think that you have done enough to 'atone' for the accident of your ship falling to this place from my skies.  I can see that you have all the wisdom within you already to use the element of air wisely.\n\nTake this portion of my being back to Farseer Nobundo so that he might help you fashion your totem.  And when you're ready, I will fly you back down to the Exodar.", sourceObjective = "Return to Farseer Nobundo at the Exodar on Azuremyst Isle with the Whorl of Air.", progress = "Back so soon?  Your hair looks ruffled.\n\n<Nobundo grins knowingly.>", completion = "I am proud of you, {name}.  You have persevered where others falter, and in the process you've gained a greater understanding of the elements and yourself.  Remember their lessons as you go through life and you will be the wiser for it.\n\nNow, hand me the whorl from Susurrus so that I may imbue it into your air totem.  As with the other totems, it will serve as both a focus and a reminder of the connection that you have forged with the elements.", sourceObjectiveStatus = "unverified-source-field" }
quests[9555] = { id = 9555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Fire", description = "I am thankful that you have chosen the difficult path of the shaman. Few enough do, but I foresee it as critical to our future that we learn shamanism from the Broken.\n\nThey are called that, but once they were draenei. Fel magics transformed them, and that is why they cannot call upon the power of the Light. Some disapprove of them and the shamanism they teach, but they are not evil.\n\nI wish you to speak with Farseer Nobundo. He is the wisest shaman I know and you will learn much with his guidance.", sourceObjective = "Speak with Farseer Nobundo at the Crystal Hall in the Exodar.", completion = "Greetings.  It is always heartening to meet a {race} who is open to the way of shamanism.  There are so few.\n\nYou have learned not to judge the flame for its outward appearance, just as you should not judge mine.\n\nYou are here because you are ready to create your fire totem.", sourceObjectiveStatus = "unverified-source-field" }
quests[9556] = { id = 9556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To The Victor...", description = "You've no doubt been fighting long and hard among the towers, {race}. We would like to give something back to you in return for your defense of these lands, but first, you must prove to us you understand the weight of the tragedies that took place here.\n\nWalk the streets of Stratholme and find a vial of the holy water. Once you have it, travel to the mage quarter of Stormwind or the Undercity... There, if you are victorious within these lands, you will find my colleague.", sourceObjective = "Collect a bottle of Stratholme Holy Water from within the city of Stratholme and deliver it to the Lordaeron Mage within the Mage Quarter of Stormwind or the Undercity when your side is victorious in the Eastern Plaguelands.", sourceObjectiveStatus = "unverified-source-field" }
quests[9557] = { id = 9557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deciphering the Book", description = "Lacking the means to read the book's contents, you think about who might be able to help you separate the author's words from the mapmaker's scrawl.\n\nRemembering Anchorite Paetheus's collection of artifacts from countless cultures, you wonder if his experienced eye might be able to help you decipher the book's contents.", sourceObjective = "Take the Ancient Journal to Anchorite Paetheus in Blood Watch.", progress = "The Light shine upon you in all your endeavors, {class}. What is it you have there?", completion = "Hmm... this is most intriguing. Yes, I should be able to make out what the original author wrote in the pages of this book.\n\nI should have everything I need for the process. This should only take a moment.", sourceObjectiveStatus = "unverified-source-field" }
quests[9558] = { id = 9558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Longbeards", description = "We were having a problem with arakkoa bandits raiding many of our supply caravans, so I hired some dwarves to take care of them.\n\nThey were brothers; Gremni Longbeard was the oldest.\n\nI'm a little worried about them.  Those crazy dwarves packed more ale than food or ammunition!  Maybe you can go check up on them?\n\nThe arakkoa's hideout, the Den of Haal'esh, can be found to the far west of here - beyond the Great Fissure.  They set up camp northwest of there, south of Dustquill Ravine.", sourceObjective = "Look for Gremni Longbeard northwest of the Den of Haal'esh, to the far west of Honor Hold in Hellfire Peninsula.", completion = "How'd you find us, {class}?  No matter, I imagine you were sent here to give us a hand.  Let's get to work then!", sourceObjectiveStatus = "unverified-source-field" }
quests[9559] = { id = 9559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stillpine Hold", description = "Promised one, you must travel north to the home of my people - Stillpine Hold. It is there that you will face your most daunting challenge.\n\nGo now, High Chief Stillpine awaits your arrival.", sourceObjective = "Speak with High Chief Stillpine at Stillpine Hold.", completion = "For centuries, we lived in relative peace with the creatures of the land. Several months ago, Kurz began to see dark omens. The peace that we enjoyed for so long was to be lost. The extent of the catastrophe could not be known!\n\nSo it would be that the gods would shatter our land - turning both friend and foe against us. But there was something else... Amidst the chaos, a hero would rise: A hero not of Stillpine blood. The Promised One would deliver us from devastation.\n\nThat prophesied hero was you.", sourceObjectiveStatus = "unverified-source-field" }
quests[9560] = { id = 9560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beasts of the Apocalypse!", description = "My brother and I were hunting in the woods to the east when we were ambushed by strange, insect-like beasts. Such aberrations have never before been seen in Azuremyst! Could they be a sign of the coming apocalypse? The apocalypse that YOU are destined to prevent?\n\nIf you truly are the Promised One, you will strike the creatures of the apocalypse down... and bring me their hides. From their hides, I can fashion armor of great power!\n\nFind them to the east, beyond the road.", sourceObjective = "Moordo at Stillpine Hold on Azuremyst Isle wants you to bring him 8 Ravager Hides.", progress = "They are ugly little creatures. Even the Blind Watcher could see them... and he's blind.", completion = "Not only is the prophecy true, this armor is also amazing! Surely it is armor fit for a champion! And I will sell it to you at discounted prices, furless one.\n\nI jest... The first piece is complimentary.", sourceObjectiveStatus = "unverified-source-field" }
quests[9561] = { id = 9561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nolkai's Words", description = "The translation is ready now, {name}.\n\n<Anchorite Paetheus points out a block of text at the end of his translation.>\n\n'The enemy is nearly upon us. We've gathered up all the survivors and retreated to the temple to the east. It's the last ground we truly hold on the island, and there is a sense among the survivors that we will make our last stand here. I've taken care to bury my last few possessions on the grounds of the temple, with the hope that someone will find them and know what happened here.'", sourceObjective = "Find the location described in Nolkai's journal and discover his long-buried possessions.", completion = "Grasses and shrubs cover an unnatural bulge in the earth.\n\nA few minutes spent digging reveals an old box, almost certainly the one mentioned in Nolkai's journal.", sourceObjectiveStatus = "unverified-source-field" }
quests[9562] = { id = 9562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murlocs... Why Here? Why Now?", description = "These are dark days, Promised One. Even the murlocs are kicking our tails - literally. Unfortunately, more than just my ego has been bruised.\n\nWhile our relationship with the Siltfin murlocs had always been tenuous, never could we have imagined that they would have the gall to attack us and steal from our food stores! Travel west to the Silting Shore and recover our stolen food-stuffs!\n\nAnd if you see a dark-skinned murloc with a patch of white fur stuck in between his webbed toes...", sourceObjective = "Gurf at Stillpine Hold on Azuremyst Isle wants you to recover 5 sacks of Stillpine Grain.", progress = "A murloc kicked me in the behind and spit on me... in broad daylight!", completion = "Mmmmm... Delicious grain... Parkat will be delighted!", sourceObjectiveStatus = "unverified-source-field" }
quests[9563] = { id = 9563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gaining Mirren's Trust", description = "So you want to gain our trust?  I don't trust many people these days.\n\nWe lost one of our own not long ago to the arakkoa.  It's got me a bit on edge.\n\nTell you what, if you can prove your loyalty to Honor Hold and... bring me a mug of Nethergarde Bitter... yes, that sounds rather good about now... I'll have a deal to offer you then.\n\nBernie at Nethergarde Keep keeps the bitter in stock.", sourceObjective = "Mirren Longbeard wants you to bring him 1 Nethergarde Bitter. You must also attain Friendly reputation with Honor Hold to complete this quest.", progress = "Having trouble finding the bitter?  Good old Bernie at Nethergarde Keep should stock barrels of it.\n\nUnless he's run out... that would be disastrous!", completion = "Why, yes!  You seem to be quite an OK {race}.  I suppose I can trust you.", sourceObjectiveStatus = "unverified-source-field" }
quests[9564] = { id = 9564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gurf's Dignity", description = "You recover the piece of fur that Gurf had \"lost\" in his struggle with the murlocs. Return the fur to Gurf and let him know that the fearsome Murgurgula has been slain.", sourceObjective = "Return Gurf's Dignity to Gurf at Stillpine Hold on Azuremyst Isle.", progress = "Is that what I think it is?", completion = "<Gurf spits on the clump of fur and tries to affix it to the hairless patch on his backside.>\n\nThis will have to do for now! Hopefully one of the shaman will be able to repair the damage.", sourceObjectiveStatus = "unverified-source-field" }
quests[9565] = { id = 9565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Search Stillpine Hold", description = "As High Chief, my immediate concern is the root of the corruption in Stillpine Hold.\n\nWhy did the wildkin - once our allies - attack us? Why have they taken residence in Stillpine Hold?\n\nPerhaps something inside will hold the answer. Search Stillpine Hold for clues as to the source of corruption.", sourceObjective = "Search Stillpine Hold for clues.", completion = "The blood crystal radiates a sickly aura that seeps into the water of the cave.", sourceObjectiveStatus = "unverified-source-field" }
quests[9566] = { id = 9566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Crystals", description = "On the surface, the crystal appears to be a piece of the Exodar. Something has gone terribly wrong with this crystal, however, as it is blood red and rapidly dissolving into the water supply of the cave.\n\nThis may explain the unusually aggressive behavior of the creatures in Azuremyst. Return to High Chief Stillpine with this information.", sourceObjective = "Speak with High Chief Stillpine at Stillpine Hold.", completion = "These blood crystals that you saw; my scouts have seen many more to the north.\n\nI thank you for aid but now ask that you leave me to confer with the elders. I will call for you once I have spoken with the other elders of the village.", sourceObjectiveStatus = "unverified-source-field" }
quests[9567] = { id = 9567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Know Thine Enemy", description = "It's good to see another new face here in Blood Watch, {class}. Although the blood elves are the most immediate threat, there are other sinister creatures that call Bloodmyst Isle home.\n\nThe Nazzivus satyr are of particular concern. They are foul, demonic creatures, commanding dark magics and feeding on the corruption created by the Exodar's crash.\n\nWe must hold them in check, but first we must learn more about them. Go southwest to Nazzivian and learn what you can from their grotesque monument.", sourceObjective = "Find the Nazzivus Monument in Nazzivian and retrieve a Nazzivus Monument Glyph. Return to Vindicator Aalesia in Blood Watch when you have one of the glyphs.", progress = "Were you successful in obtaining knowledge of the Nazzivus satyr?", completion = "Well done, {name}. Let me see what I can learn from this glyph, so we can plan our next move.", sourceObjectiveStatus = "unverified-source-field" }
quests[9568] = { id = 9568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On the Offensive", description = "It's worse than I had imagined, {name}. We draenei know well what comes of selling one's soul to the Burning Legion in return for promises of power and immortality.\n\nThe satyr on this island, the Nazzivus, are descendents of that first, twisted creature who allied with the Legion. I fear that they will find a way to use the power of the Exodar's crystals against us.\n\nYou've seen what they've done to the land. Imagine what the satyr could do with them. Go southwest to Nazzivian and begin our offensive!", sourceObjective = "Vindicator Aalesia at Blood Watch wants you to kill 10 Nazzivus Satyr, 5 Nazzivus Rogues, and 5 Nazzivus Felsworn.", sourceObjectiveStatus = "unverified-source-field" }
quests[9569] = { id = 9569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Containing the Threat", description = "Now that we have made our presence known to the satyr, we must send a message that we will not tolerate the Burning Legion's hounds in these lands.\n\nToo long have the draenei fled in the wake of the Legion and its minions, {name}. Wherever they have found us, they have shown no mercy.\n\nWe must not permit the satyr to exploit the Exodar's crash and use the corrupted crystals as weapons. Go north to where their leader resides in Axxarien, destroy him, and recover the corrupted crystals he has been gathering!", sourceObjective = "Kill 5 Axxarien Shadowstalkers, 5 Axxarien Hellcallers, and Zevrax, then gather 5 Corrupted Crystals and return to Vindicator Aalesia in Blood Watch.", progress = "<Vindicator Aalesia seems to look through you rather than at you, her mind fixed on dealing with the satyr.>\n\nHave you moved against the satyr leader as I have asked?", completion = "Without their leader, and with the recovery of the corrupted crystals underway, we can safely keep the satyr in check. Light knows how many more of these wretched creatures are out there.\n\nHarbinger Mikolaas and I are grateful for the help you've provided in dealing with the satyr before they could become a larger threat. Your work stands as a reminder that vigilance is the key to victory against the Legion and its minions.", sourceObjectiveStatus = "unverified-source-field" }
quests[9570] = { id = 9570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Kurken is Lurkin'", description = "After the crystal storm had subsided, a beast of myth appeared in our village. Brought here by the invading wildkin, this beast, the Kurken, laid waste to our village. Many Stillpine were slain in defense of our lands by this fiend and many have since lost their lives attempting to subdue the beast.\n\nIn my visions, I have seen one defeat the Kurken. The one must be you, {name}. You are our only hope. Enter Stillpine Hold and slay the Kurken. Bring me his hide as proof of deed.", sourceObjective = "Kurz the Revelator at Stillpine Hold on Azuremyst Isle wants you to kill the Kurken and bring back the Kurken's Hide.", progress = "<Kurz grunts at you.>", completion = "The Promised One has emerged victorious!\n\nThe prophecy is nearly complete. Now about that hide...", sourceObjectiveStatus = "unverified-source-field" }
quests[9571] = { id = 9571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Kurken's Hide", description = "Take the Kurken's hide to Moordo, on the other side of the village. He will fashion the hide into an item of your choice.", sourceObjective = "Deliver the Kurken's Hide to Moordo at Stillpine Hold.", progress = "Hello, hero!", completion = "This is the strongest armor I've ever made! Make good use of it, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9572] = { id = 9572, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weaken the Ramparts", description = "Quick, there isn't much time.  Thrallmar's existence balances on the razor's edge!\n\nWe're caught between Hellfire Citadel in the west and the Burning Legion to the east.  With the Legion's attention turned toward the Dark Portal we must take this opportunity to strike at the fel orcs of Hellfire Citadel.  The key to this is to first break through their ramparts!\n\nGo there, slay their leaders, and then bring back proof to Caza'rez across the room from me!", sourceObjective = "Slay Watchkeeper Gargolmar, Omor the Unscarred and the drake, Nazan. Return Gargolmar's Hand, Omor's Hoof and Nazan's Head to Caza'rez at Thrallmar in Hellfire Peninsula.", progress = "{name}, right?  Stok'ton told me to be expecting your report.\n\nI trust that you bring good news?", completion = "It's a good start.  With those three dead their forces should be in disarray.  And with their artillery up there silenced we'll have an easier time getting close enough to take the citadel!\n\nBut there's more to this than meets the eye - I can feel it - so I'm going to have something else for you to do.\n\nFor the time being, though, you've done well.  Take your pick of any of these from the Thrallmar armory.", sourceObjectiveStatus = "unverified-source-field" }
quests[9573] = { id = 9573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chieftain Oomooroo", description = "I am Stillpine the Younger, heir to the Stillpine legacy. As you can see, my defenders have set up a death trap for the raving wildkin that attack from inside Stillpine Hold. While we are able to hold them off out here, none of my defenders have been able to infiltrate the hold. If you could get inside and slay their leader, it might give us an opportunity to strike!\n\nFind Chieftain Oomooroo and destroy him. Slay any crazed wildkin that you encounter inside as well.", sourceObjective = "Stillpine the Younger at Stillpine Hold on Azuremyst Isle wants you to slay Chieftain Oomooroo and 9 Crazed Wildkin.", completion = "This may very well be the opportunity that we needed! I will send an attack at once! The Stillpine thank you for your service, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[9574] = { id = 9574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victims of Corruption", description = "Bloodmyst Isle was forever changed by our arrival. The Exodar's crash scattered debris all over the islands and I think it's beginning to have an adverse effect on the wildlife.\n\nBefore I can be certain of my conclusion, I'll need to get a closer look. The crystals seem to have affected the trees the fastest, so it seems that the treants would be the most likely to show symptoms. If you bring me samples of bark from corrupted treants, I can begin my in-depth studies.", sourceObjective = "Bring 6 pieces of Crystallized Bark to Morae in Blood Watch.", progress = "Were you able to get the samples I need?", completion = "There's more than enough here for my research. Thank you, {name}. If you find any other evidence that the crystals are corrupting Bloodmyst's native creatures, let me know right away.", sourceObjectiveStatus = "unverified-source-field" }
quests[9575] = { id = 9575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weaken the Ramparts", description = "Quick, {class}, there isn't much time.  Honor Hold's existence balances on the razor's edge!\n\nWe're caught between Hellfire Citadel in the west and the forces of the Burning Legion to the east.  With the Legion's attention turned toward the Dark Portal we must take this opportunity to strike at the fel orcs of Hellfire Citadel.  The key to this is to first break through their ramparts!\n\nGo there, slay their leaders, and then bring back proof to Gunny across the hall here from me!", sourceObjective = "Slay Watchkeeper Gargolmar, Omor the Unscarred and the drake, Nazan. Return Gargolmar's Hand, Omor's Hoof and Nazan's Head to Gunny at Honor Hold in Hellfire Peninsula.", progress = "{name}, right?  Chadwick told me to be expecting your report.\n\nWHAT are you doing in my presence?!  Is your assignment complete?  Are you a complete and utter lackwit?  You make me want to vomit!\n\nNow get your worthless hide up on those ramparts and do what you were instructed to do!  Do you hear me?!", completion = "Do you know what I hate worse than being wrong? Losing gold on a bet that you couldn't pull it off, sweetheart.\n\nOutstanding!  With those three dead their forces should be in disarray.  And with their artillery up there silenced we'll have an easier time getting close enough to take the citadel!\n\nI have a feeling there's more to this than meets the eye, though - so I'm going to have something else for you to do.  Here, take one of these from the armory.", sourceObjectiveStatus = "unverified-source-field" }
quests[9576] = { id = 9576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cruelfin's Necklace", description = "Examining the crudely constructed pendant, you notice the crystal pulsating softly. Though it emits little light, you can almost feel the crystal radiating a sense of wrongness.\n\nYou're not quite sure what might have possessed Cruelfin to create this pendant, but the find is too important to ignore. You should probably show it to someone at Blood Watch.", sourceObjective = "Bring the Red Crystal Pendant to Morae at Blood Watch.", progress = "What is it you have there?", completion = "This is most curious, {class}. I don't believe we've ever seen the murlocs wearing any kind of adornment before.\n\nGiven the corrupting influence that the crystal shards are known to have, the murloc that wore this pendant must have believed it granted him power over his fellows. I wouldn't be surprised if he had rapidly outgrown his fellow murlocs and gained in strength.", sourceObjectiveStatus = "unverified-source-field" }
quests[9578] = { id = 9578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Searching for Galaen", description = "Do you think often of your family, {name}? There were a number of families aboard the Exodar, but I've heard of very few being reunited.\n\nI, myself, am looking for traces of my husband Galaen, who was a technician in the Cryo-Core. The wreckage of it is located to the west, and it's swarming with blood elves!\n\nI must find out what became of Galaen! Even news of his death is better than never knowing. My husband will be wearing a pendant identical to my own; they were a gift from my sister.", sourceObjective = "Search for Morae's husband Galaen.", completion = "The corpse appears to be dressed in the manner of an Exodar technician, but the pendant described by Morae is absent.", sourceObjectiveStatus = "unverified-source-field" }
quests[9579] = { id = 9579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Galaen's Fate", description = "You have no means of identifying the corpse as Galaen with the information Morae gave you, but the clothing appears to have been torn in search of valuables.\n\nThe blood elves in the area would've claimed anything of value from the wreckage, including Galaen's jeweled amulet.\n\nAlthough her husband did not survive the crash, you believe that Morae would be grateful if you recovered her husband's amulet from the blood elves.", sourceObjective = "Bring Galaen's Amulet to Morae at Blood Watch.", progress = "<Morae looks at you hopefully.>\n\nDid your search turn up any trace of Galaen?", completion = "<You tell Morae of your findings in the wreckage of the Cryo-Core.>\n\nSo... he's...\n\nI guess I knew on some level, but just wouldn't let myself believe it. It's not the news I was hoping for, but you have my deepest thanks for finding Galaen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9580] = { id = 9580, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bear Necessities", description = "As I'm sure you've seen in your time on Bloodmyst Isle, very little remains unchanged by our arrival. My training and experience has taught me that even the products of an environment like this one can be put to use.\n\nWith so few resources, we must rely on our ingenuity to provide for us. I've been supplementing our stores with meat from the bears that wander this island. With the proper preparation, it can safely be eaten. If you're going to be out in the field, why not help replenish our stocks?", sourceObjective = "Bring 8 Elder Brown Bear Flanks to Tracker Lyceon in Blood Watch.", progress = "How goes the hunt, {name}?", completion = "This will keep us supplied for quite a while, and preparing it for consumption will certainly keep me busy. Thank you for your help, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9581] = { id = 9581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning from the Crystals", description = "Welcome to Blood Watch, {class}. Seeing to the defenses of the outpost is my primary concern, but I've also been tasked with a variety of other duties by our leaders at the Exodar.\n\nThe problem is that it's hardly safe to send out large amounts of researchers when the island is this dangerous. I need someone to gather a series of crystal samples from various sites on the island.\n\nThe first sample I need must come from the ravager infested ship debris south of the town and across the bridge.", sourceObjective = "Get an Impact Site Crystal Sample using the Crystal Mining Pick on the Impact Site Crystal and bring it to Harbinger Mikolaas in Blood Watch.", progress = "Were you able to gather the first crystal sample?", completion = "This crystal shard will give our researchers a baseline to compare against samples from other parts of the island, since it comes from one of Bloodmyst's less corrupted regions.\n\nI won't be able to send it off until we have a full set of samples, but this is a great start. If you're willing to help gather the other samples, I'll see to it that you're rewarded for your efforts.", sourceObjectiveStatus = "unverified-source-field" }
quests[9582] = { id = 9582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strength of One", description = "When the ship crashed, our menagerie was scattered on the northeast beaches of this isle.  I have been handed a key that unlocks the cage holding one of the deadlier specimens, a death ravager.  The creature is little armored but resistant to most magic.  It must be killed by a simple blade.\n\nTake this key and release the creature from both its prison and its pain.  We cannot afford to have it escape and cause even more damage to the ecology than we already have.", sourceObjective = "Unlock the Ravager Cage and kill the Death Ravager, then return to Ruada at Azure Watch in Azuremyst.", progress = "Have you put down the beast?", completion = "<Ruada nods solemnly.>\n\nThen it is done.\n\nYou are ready for your next lesson, {name}, but I will not be the one to teach it to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[9584] = { id = 9584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Second Sample", description = "Now that we have the baseline crystal, we're going to need samples from more dangerous areas of the island to complete the set I'll be sending to the Exodar.\n\nThe next sample must come from the crystals controlled by the blood elves in the Bladewood area to the northwest of Blood Watch. I have heard reports that they alter and harvest the crystals for use in some magical apparatus. See if you can find one that has not yet been incorporated into one of their devices, and mine a sample from it.", sourceObjective = "Get an Altered Crystal Sample using the Crystal Mining Pick on the Altered Bloodmyst Crystal and bring it to Harbinger Mikolaas in Blood Watch.", progress = "Do you have the second crystal sample?", completion = "<Harbinger Mikolaas examines the crystal shard.>\n\nThis shard is much different from the initial sample.\n\n<Harbinger Mikolaas holds the crystal up to catch the light.>\n\nDo you see how it pulsates like that? That's worrisome. I'll make a note in my report of the alterations the blood elves appear to have made to this crystal. Thank you again for your help, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9585] = { id = 9585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Sample", description = "There's just one sample remaining before I can send this set of crystals to the Exodar, {name}. The final sample must come from the satyr stronghold of Axxarien to the northwest.\n\nI'm not certain what to expect from this crystal sample, but I'm sure there will be some signs of corruption. Take care to mine your shard from the crystal that looks like the ones you took your previous samples from, or else our researchers cannot make a valid comparison.", sourceObjective = "Get an Axxarian Crystal Sample using the Crystal Mining Pick on the Axxarien Crystal and bring it to Harbinger Mikolaas in Blood Watch.", progress = "Have you returned with the last sample for my set?", completion = "<Harbinger Mikolaas accepts the last crystal from you.>\n\nThat rounds out the set. All that remains to be done is to box them and send them to the Exodar.\n\n<The harbinger seems glad to be done with the task.>\n\nDon't get me wrong, {name}, I'm sure the research is valuable, but we're faced with a number of other pressing problems out here.", sourceObjectiveStatus = "unverified-source-field" }
quests[9586] = { id = 9586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Help Tavara", description = "Tavara, one of our herbalists, has been gone far too long in her search for herbs.  I fear she is hurt and in need of help, yet I cannot look for her myself.\n\nPlease find her and lend your healing if needed, fellow {class}.  She was heading east towards some hot springs when she left Azure Watch.", sourceObjective = "Guvan at Azure Watch wants you to find Tavara and heal her wounds.", progress = "Have you found Tavara?", completion = "Thank you for helping Tavara.  So many are unfamiliar with these lands and find trouble where they least expect.\n\nIt would honor me if you were to wear these robes.  They mark you as one of the protectors of Azure Watch and a devout follower of the Light.", sourceObjectiveStatus = "unverified-source-field" }
quests[9587] = { id = 9587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Tidings", description = "Giving the lifeless form of Vazruden the Herald the once-over, you discover a rolled letter, its seal yet unbroken.  An elaborate \"I\" is pressed within the blood-red ink.  Cracking the note open, the message that you read is most disturbing.\n\nForce Commander Danath Trollbane back at Honor Hold will definitely want to take a look at this!", sourceObjective = "Take the Ominous Letter to Force Commander Danath Trollbane at Honor Hold in Hellfire Peninsula.", progress = "What's that you have there, son?", completion = "It's signed by Illidan you say?! Let me have that.\n\n<The commander reads the letter, and then again a second time, thinking a moment before going on.>\n\nThis news that you bring is ominous indeed. Knowing this, we must accelerate our plans against Hellfire Citadel and this Blood Furnace. Because you have shown that you can get the job done, I want you to head up those plans.\n\nGunny will give you your next mission, though I suspect it will be far deadlier than your first.\n\nLight be with you, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[9588] = { id = 9588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Tidings", description = "Giving the lifeless form of Vazruden the Herald the once-over, you discover a rolled letter, its seal yet unbroken.  An elaborate \"I\" is pressed within the blood-red ink.  Cracking the note open, the message that you read is most disturbing.\n\nNazgrel back in Thrallmar will definitely want to take a look at this!", sourceObjective = "Take the Ominous Letter to Nazgrel at Thrallmar in Hellfire Peninsula.", progress = "What is that letter you have there, {class}?", completion = "It's signed by Illidan you say?! Let me have that.\n\n<Nazgrel reads the letter, and then again a second time, thinking a moment before going on.>\n\nThis news that you bring is ominous indeed. Knowing this, we must accelerate our plans against Hellfire Citadel and this Blood Furnace. Because you have shown that you can get the job done, I want you to head up those plans!\n\nCenturion Caza'rez will give you your next mission, though I suspect it will be far deadlier than your first.\n\nLok'tar ogar, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[9589] = { id = 9589, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blood is Life", description = "That letter is going to get folks all riled up around here.  They'll think there's something we might do about all those new fel orcs being created if only we knew how it was being done.  It's bad enough that we have to fight the Burning Legion to the east.\n\nSo, it's your lucky day, sweetness!  You get to take a stroll into what they call the Blood Furnace inside Hellfire Citadel.  Sounds hot!\n\nGet in there, kill some fel orcs and bring back samples of their blood.\n\nYou think you can handle that?", sourceObjective = "Collect 10 Fel Orc Blood Vials and return them to Gunny at Honor Hold in Hellfire Peninsula.", progress = "You have that blood, darlin'?  Might be kind of important if we asked you to get it, you know?", completion = "Out-frikkin-standing!  As of right now Private {name}, you are my favorite person on the sorry remains of this sorry planet!\n\nI'm sure that the eggheads are going to wet themselves when I hand that blood over to them for study.  Who knows, maybe we'll find a new weapon in the fight against those damned fel orcs?", sourceObjectiveStatus = "unverified-source-field" }
quests[9590] = { id = 9590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blood is Life", description = "That letter is disturbing, and not just because it comes from the Betrayer.  We must know how they are creating these new fel orcs if we're to defeat them!  It's bad enough that we must fight the Burning Legion on our eastern flank, but now a new army of fel orcs to the west!\n\nYou must infiltrate this Blood Furnace inside Hellfire Citadel.  Bring back samples of blood from the fel orcs that you find in there.", sourceObjective = "Collect 10 Fel Orc Blood Vials and return them to Centurion Caza'rez at Thrallmar in Hellfire Peninsula.", progress = "Surely you have not collected all of the blood so quickly?", completion = "I am impressed with your abilities, {name}.  Not once, but twice now you have infiltrated Hellfire Citadel for us and accomplished what was asked of you.\n\nI will see to it that this blood is delivered to those who can unlock its mysteries.  Who knows, perhaps we can find a way to reverse the process?", sourceObjectiveStatus = "unverified-source-field" }
quests[9591] = { id = 9591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taming the Beast", description = "When the {class} first begins <his/her> path, <he/she> learns only to kill.  Now it seems you are ready for more.\n\nThe Stillpine furbolgs have provided a means to master the skill of taming without months of study.  They are able to carve a totem into the likeness of an animal, which you can use to temporarily bond with a creature of that type.\n\nFor your first lesson, take this totem and use it on the barbed crawlers found along the western coast of the isle.", sourceObjective = "Use the Taming Totem to befriend a Barbed Crawler and return to Huntress Kella Nightbow when you have succeeded.", progress = "Were you able to harness the magic of the totem to befriend a barbed crawler?  They are feisty little creatures!", completion = "I'm sure the first thing you learned was how unsympathetic the crawler was during the bonding process.  It's all claws until they know you aren't there to throw them into a boiling pot.", sourceObjectiveStatus = "unverified-source-field" }
quests[9592] = { id = 9592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taming the Beast", description = "The crawler was undoubtedly mean, but the timberstrider will test your resolve.  More powerful allies require more tenacity from the hunter.\n\nTake this taming totem and befriend a greater timberstrider.  They are found in the northern reaches of Azuremyst Isle.", sourceObjective = "Use the Taming Totem to befriend a Greater Timberstrider and return to Huntress Kella Nightbow.", progress = "The timberstrider is a powerful bird, often misjudged by predators with dire results.", completion = "Looks like the timberstrider didn't peck your eyes out.\n\n<Kella looks away for a moment.>\n\nNot that I thought that would happen, of course!", sourceObjectiveStatus = "unverified-source-field" }
quests[9593] = { id = 9593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taming the Beast", description = "You probably noticed the big cats known as nightstalkers when you tamed the timberstrider.  They are efficient and deadly hunters... and allies.\n\nUse this taming totem to befriend a nightstalker.  Hunt with the vicious cat and keep it from harm.  When you are finished, return to me.", sourceObjective = "Use the Taming Totem to befriend a Nightstalker and return to Huntress Kella Nightbow.", progress = "The nightstalker is basically a big kitty with razor sharp claws and an appetite for flesh...", completion = "I must say, {name}, you have learned far more quickly than I first imagined.  Looks like we won't need to use this last taming totem.  And honestly, I'm not even sure what it is.  It appears to be some sort of monstrous lizard with wings and a long tail.  Oh well, perhaps another time!\n\nYou've experienced enough to try it on your own now, without the aid of a taming totem.  Good luck!", sourceObjectiveStatus = "unverified-source-field" }
quests[9594] = { id = 9594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signs of the Legion", description = "The armor scrap is forged from a deep black metal that seems to absorb light. Although it doesn't appear to be enchanted, there is an unmistakable sense of wrongness about it.\n\nSuch armor is only used by one force - the Burning Legion. The Legion's presence here can only mean that they're intending to mobilize the island's satyr against the draenei.\n\nTake action against the local satyr, then return to Blood Watch and show this armor scrap to Vindicator Aalesia.", sourceObjective = "Kill 8 Nazzivus Satyr and 8 Nazzivus Felsworn, then bring Tzerak's Armor Plate to Vindicator Aalesia in Blood Watch.", progress = "Yes, {class}? What is it you have there?", completion = "You've done well in bringing this to me, {name}. This is, without a doubt, an armor fragment from a felguard.\n\nThen, it is as I feared. The Nazzivus satyr are renewing their contacts with the Burning Legion. If we don't stop them, the satyrs and their demonic allies will overrun us. I will notify Harbinger Mikolaas right away.", sourceObjectiveStatus = "unverified-source-field" }
quests[9595] = { id = 9595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Control", description = "You have chosen the path of the {class}, and so you must learn control. Magic, when unchecked, can corrupt souls and destroy worlds.\n\nTo fully understand, you must face one who has been consumed by magic. Travel to the beaches on the northwest coast of Azuremyst Isle and use your spells to decimate the murlocs. The display of power will attract the attention of the evil force lurking there, a Quel'dorei magewraith. Defeat it.\n\nWhen you have finished, seek out Bati at the Vault of Lights in the Exodar.", sourceObjective = "Kill Murlocs of the Silting Shore to summon a Quel'dorei Magewraith, then destroy it. Afterwards, speak with Bati at the Vault of Lights in the Exodar.", completion = "With every spell you must steel yourself against its seductive lure, using it only as needed for the purposes of good.  Hopefully the wraith granted a glimpse of what you might turn into should you become careless--a mindless slave to magic.", sourceObjectiveStatus = "unverified-source-field" }
quests[9598] = { id = 9598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Redemption", description = "I am responsible for putting paladins on the path to greater virtue as they devote themselves to the Light and defend our people from threats.\n\nThe time has come for you to take your first step towards being truly virtuous. If you accept it, I will give you a tome of divinity. In studying it, you shall learn some about the Light, and what is expected of you. If you understand it, and are capable, then you will succeed in attaining greater abilities.", sourceObjective = "Study the Tome of Divinity and speak with Jol.", progress = "Welcome back, {name}.", completion = "You've spent time reading the book, I hope?\n\nThen you should be prepared to have yourself tested. There are always tasks to be done in the wake of the Exodar's crash throughout these new lands: acts of compassion and understanding...people who need help...creatures to slay...\n\nBy proving you have the patience to help others, especially those who are less fortunate, you prove that you are a servant of the Light and of sound mind.", sourceObjectiveStatus = "unverified-source-field" }
quests[9600] = { id = 9600, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Redemption", description = "Your task then, {name}, is to aid our new allies, the Stillpine furbolgs.\n\nSeveral of the younger Stillpine shaman stumbled across a Bristlelimb camp and were slaughtered to the last.  Take this Symbol of Life and resurrect one of the shaman.\n\nBristlelimb Enclave is located to the east of the road just after you cross the bridge spanning Azuremyst and Bloodmyst Isle.  Speak with me when you have done this.", sourceObjective = "Jol wants you to resurrect a Young Furbolg Shaman with the Symbol of Life and return to her.", completion = "Do not distress the bewilderment shown by those you have helped.  It is common for those recently brought back to the world of the living to experience disorientation, but imagine the shock of meeting with a strange being at the same time.\n\nThe young shaman is blessed to have survived such a harsh lesson thanks to you, and it is befitting you be allowed to call upon this power as you see fit.", sourceObjectiveStatus = "unverified-source-field" }
quests[9601] = { id = 9601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To The Bulwark", description = "The blood knight Mehlar Dawnblade has requested an audience with you, {name}.  Mehlar can be found at the Bulwark, guarding the passage between Tirisfal Glades and the Western Plaguelands.\n\nHe is not known for his patience.  It would not be wise to keep him waiting.", sourceObjective = "Speak with Mehlar Dawnblade at the Bulwark.", completion = "Ahh... it seems it is time.\n\n<Mehlar nods knowingly.>", sourceObjectiveStatus = "unverified-source-field" }
quests[9602] = { id = 9602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deliver Them From Evil...", description = "You must get this information to your people, {name}. While your brave acts have certainly slowed down the plans of Kael'thas and his dark master, the attacks will undoubtedly continue.\n\nTake the traitor's communication to your leaders. They must see this for themselves. Perhaps they will be able to better understand some of what was written.", sourceObjective = "Deliver the Traitor's Communication to Exarch Menelaous at Azure Watch.", progress = "You have returned!", completion = "<Exarch Menelaous takes the letter from you and begins to read it.>\n\nDamn them... Damn them all to the Nether. They've had a spy watching everything that we've done! And for how long?\n\nI will notify Velen at once!\n\nYou've done us a great service, {name}. Be on guard as I will be contacting you once the Prophet has given me instruction as to what to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[9603] = { id = 9603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beds, Bandages, and Beyond", description = "Welcome to Blood Watch, {class}. Please excuse the disorder you see around you. It's easy to take simple things for granted, like a fully furnished and stocked inn, until you're forced to build one from nothing.\n\nWe've managed to salvage this pod for a building, but without the proper furnishings and first aid supplies, the inn is little more than a glorified tent. Nurguni at the Exodar has offered to put together a package to help with our most immediate needs, but I need someone to deliver this list to him.", sourceObjective = "Take Topher's List to Laando, the Hippogryph Master at Blood Watch.", progress = "Good day, {name}. Are you interested in renting a hippogryph?", completion = "So you need to go to the Exodar?\n\nThat's going to be a long trip, but don't worry, I have a way to get you there very quickly.", sourceObjectiveStatus = "unverified-source-field" }
quests[9604] = { id = 9604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On the Wings of a Hippogryph", description = "For a small fee, you can rent one of my hippogryphs to fly you to the Exodar.\n\nTaking the hippogryph is a faster, not to mention safer, alternative for someone carrying an important message. If you'd like to take a ride, speak to me again and I'll make the arrangements.", sourceObjective = "Purchase a hippogryph ride to the Exodar from Laando. When you land, take Topher's List to Nurguni in the Seat of the Naaru at the Exodar.", progress = "Greetings, friend. You look like you've come a long way. How can I help you?", completion = "So you've brought Topher's list. Excellent! I was hoping to receive this today. Let's see what he needs.\n\n<Nurguni reads over the list and begins placing various items in a box.>\n\nThat's most of what he requested. The pieces for the beds are simply too large to be delivered by hippogryph, but I'll make arrangements to have them sent by wagon.", sourceObjectiveStatus = "unverified-source-field" }
quests[9605] = { id = 9605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hippogryph Master Stephanos", description = "Here's the box, {name}. That should be enough for Topher to get the inn up and running. Let him know that he can keep sending in orders as the need arises. Blood Watch urgently needs a place to care for the wounded and put up any travelers they receive.\n\nWhen you're ready to return to Blood Watch, seek out Stephanos near the gates of the Exodar.", sourceObjective = "Find Stephanos outside the Exodar and purchase a hippogryph ride back to Blood Watch.", progress = "Where are you headed, {class}?", completion = "So you're headed back to Blood Watch with this package? No problem at all, {class}. Just speak with me again and we'll get you on your way with those supplies.", sourceObjectiveStatus = "unverified-source-field" }
quests[9606] = { id = 9606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Topher Loaal", description = "If I remember correctly, Blood Watch's hippogryph master is Laando.  If you've spoken to him before, then you can take one of my hippogryphs to him.\n\nThat's a good lesson to know: hippogryphs are always trained to fly to their capital city, but they'll only take you to a remote hippogryph master after you've already been there.\n\nSince you arrived on one of Laando's hippogryphs, you can also use that route to return to Blood Watch with the caregiver's supplies.", sourceObjective = "Speak with Stephanos to purchase a hippogryph ride back to Blood Watch. Once you have arrived, deliver Nurguni's Supplies to Caregiver Topher Loaal.", progress = "Welcome back, {name}. Was Nurguni able to gather everything on the list?", completion = "<Handing Topher the box, you tell him that Nurguni is making arrangements to have the larger items delivered by wagon.>\n\nSplendid! Now, I'll finally be able to set up some beds and a first aid station so that we can better treat the wounded and any survivors we encounter.\n\nI can't thank you enough for your help, {name}. You have my thanks and that of the Blood Watch's vindicators.", sourceObjectiveStatus = "unverified-source-field" }
quests[9607] = { id = 9607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heart of Rage", description = "{class}, put together a force to investigate the Blood Furnace inside Hellfire Citadel at once!  And that means today, princess!\n\nThe magic we have at our disposal indicates that something unnatural is occurring in there.  But something more powerful inside is blocking any detailed arcane investigations.  It figures!\n\nYou can expect heavy resistance - no other mission that we've sent in there has yet to return!\n\nScout it entirely and then report back to the force commander with what you witness.", sourceObjective = "Fully investigate the Blood Furnace and then report to Force Commander Danath Trollbane at Honor Hold in Hellfire Peninsula.", progress = "Master Sergeant, report!  Have you scouted all of the Blood Furnace yet?", completion = "THEY HAVE A PIT LORD?!\n\n<The force commander looks around at the stares of the others and then lowers his voice to a whisper.>\n\nThat seals it.  They must be using the blood from this pit lord to create new fel orcs that are somehow not aligned with the Burning Legion.  And if they can do this to the brown orcs, they can do it to the green ones too.  With all of the new Horde orcs streaming in through the Dark Portal, that's not good!\n\nWe must strike at the heart of their military might, and soon!", sourceObjectiveStatus = "unverified-source-field" }
quests[9608] = { id = 9608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heart of Rage", description = "{class}, you must gather a group to investigate the Blood Furnace inside Hellfire Citadel at once!\n\nThe magical scrying that we have at our disposal indicates that something unnatural is occurring in there.  But a powerful force inside is blocking any detailed arcane investigations, so it must be very important.\n\nYou should expect heavy resistance - no other mission that we've sent in there has ever returned!\n\nScout it entirely and then report back to Nazgrel, advisor to Thrall, with what you witness.", sourceObjective = "Fully investigate the Blood Furnace and then report to Nazgrel at Thrallmar in Hellfire Peninsula.", progress = "Have you scouted all of the Blood Furnace yet?  What do you have to tell me?", completion = "THEY HAVE A PIT LORD?!\n\n<Nazgrel notices the glances of the others assembled and lowers his voice to a whisper.>\n\nThat seals it.  They must be using the blood from this pit lord to create new fel orcs that are somehow not aligned with the Burning Legion.  And if they can do this to the Mag'har brown orcs, they can do it to us!\n\nWe'll have to strike at the heart of their military might, and soon!", sourceObjectiveStatus = "unverified-source-field" }
quests[9609] = { id = 9609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Help Watcher Biggs", description = "Magtoor has informed me that there's a stranded watcher nearby.  Apparently the caravan he was escorting from Darkshire was attacked by Lost Ones.  It sounds as if he's the sole survivor.\n\nHe's somewhere to the south.  Please, {class}, lend him your aid.", sourceObjective = "Find Watcher Biggs in the Swamp of Sorrows.", completion = "What?  A draenei sent you here from the Harborage?  How odd.\n\nWell, I'm not one to turn down assistance.  Thanks for coming, {class}!", sourceObjectiveStatus = "unverified-source-field" }
quests[9610] = { id = 9610, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pool of Tears", description = "I am interested in studying Azeroth's past and I'm wondering if you'd be willing to help?\n\nThere is a nearby place of historical significance within the swamp that I would like for you to venture to.  The Pool of Tears lies to the southeast.  It is said that upon its shores and within its depths are buried artifacts of the Atal'ai troll civilization.\n\nBut beware, it is guarded by Somnus, an ancient green dragon, and his dragonkin, as well as carnivorous fish in the pool itself!", sourceObjective = "Obtain 5 Atal'ai Artifacts and return them to Holaaru at the Harborage in the Swamp of Sorrows.", progress = "I look forward to you gathering enough of the Atal'ai artifacts so that I might begin to study them.  I'm eager to discover what happened to their once-great civilization.", completion = "I thank you, {class}.  The study of these artifacts should keep me occupied for some time.  How else are we Broken and draenei to fit in if we do not come to understand the history of your world?", sourceObjectiveStatus = "unverified-source-field" }
quests[9612] = { id = 9612, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hearty Thanks!", description = "You saved my life, {name}! Thank you so much! That beast would have torn me to shreds if it weren't for you.\n\nIf you see the exarch at Azure Watch, tell him of what you did. I'm sure he'll be pleased to hear such news!", sourceObjective = "Speak with Exarch Menelaous at Azure Watch.", completion = "Well done, {name}. Well done indeed! You are turning out to be a special {race} - a cut above the others of your age. Take this as a reward!", sourceObjectiveStatus = "unverified-source-field" }
quests[9616] = { id = 9616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bandits!", description = "This appears to be a bounty ledger. You cannot understand the blood elf language but you note that there is a picture depicting a dead draenei, a smiling blood elf standing over the corpse, and a symbol of what you think is some sort of blood elf currency.\n\nThey've put a hit out on draenei! You must inform the exarch.", sourceObjective = "Take the Blood Elf Communication to Exarch Menelaous at Azure Watch.", progress = "Yes? I'm very busy, {name}.", completion = "By the beardless, geometric head of O'ros! It is good you brought this to me, {name}. These blood elves are out for... well, blood. Velen will be informed at once! Take this as a reward.", sourceObjectiveStatus = "unverified-source-field" }
quests[9617] = { id = 9617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek the Farstriders", description = "Lieutenant Dawnrunner at Farstrider Retreat has requested an audience with all able hunters.  It would greatly benefit you to seek her out, {name}.  She is a beacon of wisdom for those of our calling.\n\nFarstrider Retreat lies south of Silvermoon City.", sourceObjective = "Speak with Lieutenant Dawnrunner at Farstrider Retreat.", completion = "{name}, it is good you have come.  Our list of allies grows thin, and even those who share our cause are not completely trusted.  It is because of this that we, the rangers, turn to nature for aid.\n\nIn the allies of the forest we find a deep bond that does not know deceit.", sourceObjectiveStatus = "unverified-source-field" }
quests[9618] = { id = 9618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return the Reports", description = "Your sleight of hand was most impressive.  There's no question that I can trust you to take these reports to Zelanis.", sourceObjective = "Bring Keltus Darkleaf's Reports to Zelanis in Silvermoon City.", progress = "Were you able to locate Keltus?", completion = "All of these reports are from Keltus?  He's been quite busy, that's for sure.\n\nKeltus is a {class} among rogues--he rarely follows orders to the letter, and often takes matters into his own hands!  Don't take that wrong, however, as he is one of my most trusted spies and we would be lost without him.\n\nYou've done an exemplary job today.  Please accept this blade and guide it into our enemy's back.", sourceObjectiveStatus = "unverified-source-field" }
quests[9619] = { id = 9619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rune of Summoning", description = "The voidstone reveals a vision of a multi-story building haunted by ghostly figures.  As the scene sharpens and blurs, other buildings come into view, leading you to believe it is Goldenmist Village.\n\nRooftops and tree canopies suddenly flash by, revealing the way to Goldenmist by following the Elrendar River to the west.\n\nOnce there, use the voidstone near the rune of summoning atop the center building and defeat the summoned voidwalker.  Only then can you return to your teacher.", sourceObjective = "Use the Voidstone to summon a Voidwalker in Goldenmist Village, defeat it, and return to Talionia in Silvermoon City.", progress = "Have you followed the path revealed by the voidstone?", completion = "I'm impressed you are standing here, {name}.  Many an apprentice has perished to the voidwalker, or even the voidstone itself.\n\nThe voidwalker is now yours to command.  Use your new servant well.", sourceObjectiveStatus = "unverified-source-field" }
quests[9620] = { id = 9620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Survey Team", description = "As we've gotten ourselves established here at Blood Watch, I've been sending out survey teams to create more reliable maps of the island. In most cases, they returned unharmed with the data we need, but the team I sent east to the ruins hasn't reported back.\n\nI worry about what might have happened to them, but I can't spare the men to send another mission after them. Find them, {name}, and lend them any assistance they require to return with their survey data.", sourceObjective = "Harbinger Mikolaas wants you to find the Survey Team he sent to the Ruins of Loreth'Aran and assist them in any way you can.", completion = "The bodies of the {race} survey team are scattered all over the ground here, pierced by naga weaponry. The area is littered with the remains of their supplies and survey equipment, but their data crystals are nowhere to be seen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9621] = { id = 9621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Envoy to the Horde", description = "There were doubts about our capabilities among our potential new allies.  Of what use could we be to them when perceived as unable to deal with our problems at home?\n\nThis changes everything.  No longer will our power be questioned.  We'll be able to join the Horde as equals.\n\nTake this letter to Sylvanas, ruler of the Forsaken.  She's already on our side but the news of Dar'Khan's death will be music to her ears.  Prepare for a long trip, {name}.  If all goes well she will send you to Orgrimmar.", sourceObjective = "Bring the Letter from Lor'themar Theron to Lady Sylvanas Windrunner in Undercity, the Forsaken capital in Tirisfal Glades.", progress = "Ah, a visitor from Quel'Thalas!  What news do you bring?", completion = "It is done then.  The foul traitor got what he deserved.\n\nYou did this yourself?  An impressive feat that proves that your race remains worthy, {name}.\n\nI see that Lor'themar has additional news that will greatly improve his relations with Thrall.", sourceObjectiveStatus = "unverified-source-field" }
quests[9622] = { id = 9622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warn Your People", description = "The Hold is saved and soon my people will make their way back to the ancestral home. The prophecy has come to pass and a new age of prosperity begins for the Stillpine.\n\nBut I fear that darkness looms ahead for your own people. There are questions left unanswered - visions of prophecy unseen.\n\nReturn to your leaders and tell them of what you have seen here.\n\nAnd Promised One, should you ever require the aid of Stillpine, you have merely to ask.", sourceObjective = "Speak with Exarch Menelaous at Azure Watch.", completion = "Visions you say? Interesting... And this prophecy has come to pass?\n\nBut you say they saw the power core of the Exodar? And O'ros was also in the vision? What can it mean?", sourceObjectiveStatus = "unverified-source-field" }
quests[9623] = { id = 9623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coming of Age", description = "You have survived the wilds of our new home and shown yourself a cut above the others. I believe that you have come of age to assist those battling on the front lines of Bloodmyst. The Hand of Argus could use a {race} like you. \n\nReport to Torallius the Pack Handler. You will find him outside the Exodar, tending to the elekk. Give him these orders so that he may direct you towards your new duties on Bloodmyst.", sourceObjective = "Exarch Menelaous at Azure Watch has asked that you deliver the Exarch's Orders to Torallius the Pack Handler, standing outside of the Exodar.", progress = "<Torallius adjusts his eyepatch to look at you.>\n\nThis is the best we can offer the Hand of Argus?", completion = "<Torallius sighs.>\n\nAlright, let me have a look at those orders.", sourceObjectiveStatus = "unverified-source-field" }
quests[9624] = { id = 9624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Favorite Treat", description = "I've made a wonderful discovery, {class}. On the uncorrupted part of the island grows a remarkable fruit called the sand pear. They're found near the bottoms of the trees.\n\nI've been preparing pies from them, but if I'm not careful, the elekk will start to wander over and steal my fruit. I've taken to gathering enough to share with the animals, but my stores are gone and the craving for pie has returned. Would you be willing to help gather the fruit I need for another batch of pies? I promise I'll share!", sourceObjective = "Aonar at Kessel's Crossing wants you to bring him 10 Sand Pears.", progress = "The sand pears are getting harder to find and, of course, that means less pie and fewer treats for the elekk here. Were you able to gather all the fruit I'll need?", completion = "Did you have a difficult time finding enough? It's been taking me longer with each trip.\n\nSoon, I'll have to stop altogether since I won't be able to spare the time. Thank you for gathering the pears for me, {name}. It gives me a chance to make a last pie or two before the season's out.", sourceObjectiveStatus = "unverified-source-field" }
quests[9625] = { id = 9625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elekks Are Serious Business", description = "Is he crazy? Entrusting something like this to some no-named {race} youngling!\n\nJust remember this kid: You'll never make it as a Hand of Argus! You don't have the guts!\n\nI guess I'll have to humor him this time. Speak with Vorkhan at Kessel's Crossing on Bloodmyst Isle. Just follow the road north from here, and when it forks, just keep on going north.", sourceObjective = "Speak with Vorkhan the Elekk Herder on Bloodmyst Isle.", completion = "Well ya made it this far! Let's put ya to work before you get too bloodied up.", sourceObjectiveStatus = "unverified-source-field" }
quests[9626] = { id = 9626, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meeting the Warchief", description = "I haven't lost any love for my homeland or its people, as you know.  I've fought tooth and nail for Silvermoon to be allowed a place beside Undercity and Orgrimmar at the negotiating table.\n\nThis should silence any opposition. Take this letter to Thrall in Orgrimmar.  As leader of the Horde he will have the final say on accepting your race's pledge.\n\nI've added my own seal to the letter as a personal endorsement.  Go northwest of the city and board the zeppelin bound for Durotar at the tower.", sourceObjective = "Lady Sylvanas Windrunner wants you to take the Letter Sealed by Sylvanas to Thrall in Orgrimmar, capital of Durotar.", progress = "You've come to see me, {race}?  Speak and be quick.  I've no time for the formalities of your race.", completion = "<Thrall begins to read the letter.>\n\nSylvanas is a persistent one.  So she's sent one of Silvermoon's own champions... how does this change anything?", sourceObjectiveStatus = "unverified-source-field" }
quests[9627] = { id = 9627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allegiance to the Horde", description = "Your people suffered a great betrayal by the Alliance.  You've succeeded in fending off Darnassian attacks as well as spies from Ironforge.  Now you've defeated a powerful Scourge leader at the footsteps of your home.  Your worthiness is no longer in question.\n\nIt is now apparent that you need us and we need you.  Return to Lor'themar.  Tell him I received his message loud and clear.\n\n<The warchief crushes the letter inside his palm.>\n\nWelcome to the Horde, elf.", sourceObjective = "Return to Silvermoon City and report back to Lor'themar Theron.", completion = "Your work has helped advance our race's cause a tremendous deal.  Not only does Thrall believe we're capable of handling ourselves in the face of the enemy, he also believes he can use our link with Outland as a means to reach his people.\n\nNot exactly the truth, but not a lie either.\n\nBrace yourself for great changes, {name}.  We are now officially part of the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[9628] = { id = 9628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salvaging the Data", description = "It's too late to assist the cartographers in completing their mission, but it appears they collected the data Harbinger Mikolaas was expecting. The crystal storing their survey information was not among their ransacked packs, so it must be in the hands of the Wrathscale naga.\n\nYou know that Harbinger Mikolaas will be saddened by the loss of the survey crew, but would want to salvage the survey data.", sourceObjective = "Obtain the Survey Data Crystal from the Wrathscale near the dead cartographers and return it to Harbinger Mikolaas at Blood Watch.", progress = "Were you able to find out what was keeping the survey team from returning?", completion = "<You tell Harbinger Mikolaas of the survey team's fate. He accepts the crystal from you, but remains silent for a long moment.>\n\nThey were good men, {name}, and they knew their mission would be dangerous. I'm grateful for your help in locating the team and recovering the crystal.\n\n\n\nWe've lost too many good men already, and our mission has only just begun.", sourceObjectiveStatus = "unverified-source-field" }
quests[9629] = { id = 9629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catch and Release", description = "The Blacksilt murlocs on the southwestern coast are curious creatures. In some ways, they act barely sentient, yet in others, they show a remarkable degree of organization.\n\nI have a few theories about that, but no real way to test them until recently. I've devised a method that will allow me to track the murlocs I'm interested in without doing any lasting harm or interfering with their natural behavior. If you're willing to help with the marking, I'll gladly pay you for your assistance.", sourceObjective = "Morae at Blood Watch wants you to 'mark' 6 Blacksilt Scouts using the Murloc Tagger.", progress = "Did the device work? Have you marked the murlocs for my research?", completion = "Well done, {name}. I was worried that the marking device might malfunction, but it seems like everything went according to plan.", sourceObjectiveStatus = "unverified-source-field" }
quests[9630] = { id = 9630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Medivh's Journal", description = "Your name is getting around, {name}.  You've made your way into and out of Karazhan - more than most mortals can claim.\n\nI need to ask a special favor of you.  As part of our research, the Violet Eye has been trying to track down Medivh's own journal.\n\nUnfortunately, none of the agents we've sent inside have come out.  Wravien was the last to be sent; see if you can find him and see about any leads on the journal.", sourceObjective = "Archmage Alturus at Deadwind Pass wants you to go into Karazhan and speak to Wravien.", completion = "A vast wealth of information... I could spend years here!  I'm sure Dalaran will understand...", sourceObjectiveStatus = "unverified-source-field" }
quests[9631] = { id = 9631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Colleague's Aid", description = "There is a small detail I've forgotten to take into account.  The residue of Medivh's essence contained in this bone fragment is completely devoid of life - just like Arcanagos.\n\nThere is a way, however.  And I know just the person to help us.\n\nTravel to Area 52 in Netherstorm and show the bone fragment to Kalynna Lathred.  She will know just what to do.", sourceObjective = "Take the Charred Bone Fragment to Kalynna Lathred at Area 52 in Netherstorm.", progress = "Alturus sent you.  The stars spoke of your arrival.", completion = "Alturus wants to raise a whole dragon back from the dead?  Not an easy task by any stretch of the imagination.\n\nLet us discuss how we can be of mutual assistance, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9632] = { id = 9632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Newfound Allies", description = "Harbinger Mikolaas has done a commendable job of safeguarding Blood Watch, {class}, but our enemies are many and our resources few.\n\nOur weakness is well known to our enemies, but your contact with the forces of the Alliance is something they haven't accounted for. I have prepared a letter of introduction to the people of Auberdine, the closest Alliance settlement, proposing cooperation in the fight against our foes. Take it with you and seek out Huntress Kella Nightbow near the docks west of the Exodar.", sourceObjective = "Take the Letter of Introduction to Huntress Kella Nightbow in Azuremyst Isle.", progress = "Greetings, {class}. What have you there?", completion = "I can help you get to Auberdine. Fortunately, it's only a short boat trip away!", sourceObjectiveStatus = "unverified-source-field" }
quests[9633] = { id = 9633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Way to Auberdine", description = "If you wait out on the dock, you'll see the boat arriving from the port of Auberdine in Darkshore. Once it has offloaded its passengers, you'll be able to board.\n\nAfter a short journey, the boat will put in at Auberdine and you'll be able to deliver your message.\n\nIt's probably best to take this to Thundris Windweaver, an old friend of mine and a well-respected citizen of the town.", sourceObjective = "Take the boat from the dock near Huntress Kella Nightbow to Auberdine. Once you have arrived in Auberdine, take the Letter of Introduction to Thundris Windweaver.", progress = "Welcome to Auberdine, friend. What brings you to Darkshore?", completion = "<Thundris accepts the letter from you and reads it quickly, nodding.>\n\nThe isles the {race} call Azuremyst and Bloodmyst were inhabited long ago by my people. Some of the threats faced by Anchorite Paetheus and his brethren are ancient enemies of the night elves.\n\nI am certain that the people of Auberdine are willing to provide what aid we can to our new allies. As soon as I have spoken with the townspeople and the sentinels, I will send word to Paetheus.", sourceObjectiveStatus = "unverified-source-field" }
quests[9634] = { id = 9634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alien Predators", description = "One thing we've learned in our travels is that extreme care must be taken when introducing wildlife from one world to another. When the Exodar crashed, it was carrying specimens of various Outland species, including an insectoid predator called the ravager.\n\nSome of the specimens were lost, but many others survived and took to the wild. If we don't keep them in check, they will upset the natural balance here on the islands.\n\nYou'll find these ravagers to the west of Kessel's Crossing, near the coast.", sourceObjective = "Kill 10 Bloodmyst Hatchlings then return to Vorkhan the Elekk Herder at Kessel's Crossing on Bloodmyst Isle.", completion = "Well done, {name}. The ravager population will bear watching for some time to come, but we've made a good start.", sourceObjectiveStatus = "unverified-source-field" }
quests[9635] = { id = 9635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Zapthrottle Mote Extractor!", description = "The swamp gas is truly amazing, and can be very useful, mon!  But first, you gotta be able to suck it up, and that, my friend, requires a Zapthrottle Mote Extractor.\n\nNow, I could just give you the schematics, but I'll need something in return first.  How about some spare parts?  Last time I checked, there were plenty laying around near the broken steam pump at the Dead Mire, far to the northeast.\n\nI heard that the withered giants spread the pieces all over that dried-out lake bed.", sourceObjective = "Bring 15 Steam Pump Parts to Mack Diver at Zabra'jin in Zangarmarsh.", progress = "You got those parts yet?  I've got some diving to do.", completion = "Alright!  Now if we only had a stretchy loop, a parchment clamp, a guzzle tube and some sticky duck ribbon.  Then we could really make something!\n\nOk, ok, I guess you've earned this, {name}.  Have fun!", sourceObjectiveStatus = "unverified-source-field" }
quests[9636] = { id = 9636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Zapthrottle Mote Extractor!", description = "Have you seen the swamp gas?  Isn't it just shiny?\n\nIt takes a Zapthrottle Mote Extractor to suck 'em dry though.  I could give you the plans to make one, but I really need some spare parts to fix stuff 'round here.\n\nLast time I checked, there were plenty of parts laying around near the steam pump at the Dead Mire to the northeast.  I think the withered giants broke the pump out there.\n\nShall we help each other out?", sourceObjective = "Bring 15 Steam Pump Parts to K. Lee Smallfry at Telredor in Zangarmarsh.", progress = "You got those parts yet?  I've got a compression coil to fix before Anchorite Ahuurn starts breathing down my neck!", completion = "Shiny!  And really, what engineer ever has enough spare parts just hanging around?  Ooh, maybe I could sell off the extra and buy me some of that Tigule and Foror's Strawberry Ice Cream?!  I just love strawberries!  Do you think they have any around here?\n\nOk, ok, I guess you've earned this, {name}.  Have fun!", sourceObjectiveStatus = "unverified-source-field" }
quests[9637] = { id = 9637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kalynna's Request", description = "I left the Kirin Tor in pursuit of knowledge forbidden by those of my order; it is beyond ironic that I am now asked to assist them with that very same knowledge.\n\nIf I'm to perform this favor for you, you will have to do something for me first.  I want you to obtain two of the tomes I've been searching for.\n\nThe first one is called the Tome of Dusk and is owned by the orc warlock known as Nethekurse.  The second, known as the Book of Forgotten Names, belongs to the arakkoa known as Darkweaver Syth.", sourceObjective = "Kalynna Lathred wants you to retrieve the Tome of Dusk from Grand Warlock Nethekurse in the Shattered Halls of Hellfire Citadel and the Book of Forgotten Names from Darkweaver Syth in the Sethekk Halls in Auchindoun.\n\nThis quest must be completed in Heroic difficulty.", progress = "Have you obtained the tomes I seek, {name}?", completion = "Excellent, {name}.  I've been trying to obtain these books for a very long time.  It is fortunate that we were able to be of mutual assistance.", sourceObjectiveStatus = "unverified-source-field" }
quests[9638] = { id = 9638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Good Hands", description = "Was I supposed to be looking for this journal?  It can't be... I don't quite recall...\n\nOf course!  It is Gradav you're thinking of.  He was looking for the book when I got here.  Surely he must've found it by now; why don't you go ask him about it?\n\nI'd lend you a hand... but these books are just so... interesting!", sourceObjective = "Speak to Gradav at the Guardian's Library in Karazhan.", completion = "Can't you see I'm in the middle of something here?  What do you want?", sourceObjectiveStatus = "unverified-source-field" }
quests[9639] = { id = 9639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kamsis", description = "Journal, what journal?  You're thinking of Kamsis, surely.\n\nGo and ask her about it.  I can't leave my project right now or all my work will be wasted!", sourceObjective = "Speak to Kamsis at the Guardian's Library in Karazhan.", completion = "The journal you speak of... I was sent here to look for it wasn't I?", sourceObjectiveStatus = "unverified-source-field" }
quests[9640] = { id = 9640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shade of Aran", description = "Let me think for a second.  The Violet Eye... Medivh's Journal...  Why yes, it's all coming back to me now.\n\nI believe I had the journal you're looking for before I started to read these scrolls...\n\nAran... yes, Aran asked me for the book.  So nicely too.  I just had to give it to him.  He's Medivh's father after all, did you know?", sourceObjective = "Obtain Medivh's Journal and return to Kamsis at the Guardian's Library in Karazhan.", progress = "Weren't you looking for a journal or something?", completion = "Did you find what you were looking for?  You were looking for something, weren't you?", sourceObjectiveStatus = "unverified-source-field" }
quests[9641] = { id = 9641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irradiated Crystal Shards", description = "The Exodar's crash scattered pieces of fouled crystals all over Bloodmyst Isle, corrupting the water and the landscape.\n\nWe've even begun finding pieces of the crystals inside the flesh of animals taken for meat. I've uncovered a way to purify the shard and turn them into functional crystals, so if you bring me enough shards, I'll trade one of my completed crystals for them. So far I've found the shards in the bodies of bears, ravagers, flutterers, and treants inhabiting the corrupted part of the island.", sourceObjective = "Vindicator Boros at Blood Watch wants you to bring him 10 Irradiated Crystal Shards.", progress = "Have you gathered crystal shards from the creatures of Bloodmyst?", completion = "Well done. These will provide the raw materials for another batch of enhancement crystals.\n\nYou're welcome to choose from among the three kinds of crystals I can make. I find each of them useful for stalking different kinds of prey.", sourceObjectiveStatus = "unverified-source-field" }
quests[9642] = { id = 9642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Irradiated Crystal Shards", progress = "If you have more of the irradiated crystal shards, I'd be happy to exchange them for another of my crystals.", completion = "Very well, here are the crystals that I have, {name}. Use them well." }
quests[9643] = { id = 9643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Constrictor Vines", description = "A good woodsman makes use of every available resource, {class}. Even the most bizarre creatures possess attributes we can use to our advantage.\n\nWith Blood Watch under constant assault from the Sunhawks, we're looking to a variety of natural defenses including traps. The lasher's thorny vines are perfectly suited to the construction of the traps I have in mind. The combination of sharp spines and deadly toxin will fell unwary attackers. Bring me the vines of mutated constrictors so that I can begin my work.", sourceObjective = "Tracker Lyceon at Blood Watch wants you to bring him 6 Thorny Constrictor Vines.", progress = "Did you manage to get the constrictor vines?", completion = "These seem sturdy enough to do the job. Thank you for your help, {name}. Your contribution to Blood Watch's defense will not be forgotten.", sourceObjectiveStatus = "unverified-source-field" }
quests[9644] = { id = 9644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nightbane", description = "You fulfilled your end of the deal.  I will now bind your essence to that of the dead blue dragon.\n\nThere is an urn in the Master's Terrace, should you touch that urn, you'll now release its energy anl bring life back to the charred remains of Arcanagos.  Defeat the creature and retrieve its essence immediately!  You will need to take it to Alturus.\n\nShould you fail, the stars predict you will have let a great terror loose upon the skies.\n\nA terror known as Nightbane!", sourceObjective = "Go to the Master's Terrace in Karazhan and touch the Blackened Urn to summon Nightbane. Retrieve the Faint Arcane Essence from Nightbane's corpse and bring it to Archmage Alturus.", progress = "What news do you bring, {name}?", completion = "This is astounding!  Not only have you brought back Medivh's Journal, but you've also retrieved a fragment of his very essence.\n\nAs faint as this lingering essence is, it will reveal to us vital information about Medivh.  We will not forget this, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9645] = { id = 9645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Master's Terrace", description = "Journal?  What journal?\n\nOh, right.  That journal!  The Violet Eye sent me here for it.  It's all coming back now.\n\n<Kamsis points to a page in the journal.>\n\nThis is the page that Alturus is interested in.  Did you know that while other people's journals serve as a record of their memories, Medivh's is literally just that?\n\nTry it.  Go to the Master's Terrace and read the page; you'll see just what I mean.  Might as well report to Alturus while you're at it.  I'm afraid I'll be here for a while.", sourceObjective = "Go to the Master's Terrace in Karazhan and read Medivh's Journal. Return to Archmage Alturus with Medivh's Journal after completing this task.", progress = "You've returned!  What news do you bring?", completion = "It is a shame that the agents we sent succumbed to Karazhan's magic.  At least you managed to obtain what they were after.", sourceObjectiveStatus = "unverified-source-field" }
quests[9646] = { id = 9646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Deathclaw", description = "By order of Harbinger Mikolaas: A bounty of 18 silver to be paid to the brave soul who returns with proof of the marauding bear Deathclaw's demise.\n\nDeathclaw should be considered extremely dangerous and is responsible for the killing of a survey team on the coast to the northwest of Blood Watch. Travelers are advised to avoid the area.", sourceObjective = "Bring Deathclaw's Paw to Harbinger Mikolaas in Blood Watch.", progress = "How can I help you, {class}?", completion = "Well done. From what I've heard, it couldn't have been an easy fight. You've more than earned your reward, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9647] = { id = 9647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Culling the Flutterers", description = "When we first encountered flutterers, they showed few signs of mutation. As the corruption got progressively worse, the moths and other species began to show signs of contamination.\n\nIt has progressed to the point where they damage nearly everything they come in contact with. They're amplifying the damage being done by the crystal shards scattered by the Exodar's crash. We have no choice but to begin culling their population in the lands north of Blood Watch.", sourceObjective = "Tracker Lyceon at Blood Watch wants you to kill 10 Royal Blue Flutterers.", completion = "In time, we'll have to devise a plan for returning the species to its native state, but for now, periodically culling their numbers is about the best we can hope for. Thank you for your help, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9648] = { id = 9648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maatparm Mushroom Menagerie", description = "Did you know mushroom hunting is far more dangerous than mushroom consumption? Mushroom hunters expose themselves to many unknowns - not including potential wildlife dangers!\n\nWhat would life be without a little danger? I am in need of mushrooms for my collection. Scattered throughout these unexplored wilds you will find four different types: An aquatic stinkhorn, a blood mushroom, a ruinous polyspore, and a fel cone fungus. They are each unique to various regions in Bloodmyst. Bring them to me.", sourceObjective = "Maatparm at Blood Watch wants 1 Aquatic Stinkhorn, 1 Blood Mushroom, 1 Ruinous Polyspore, and 1 Fel Cone Fungus.", progress = "Remember, the mushrooms I requested are each unique to the different environments of Bloodmyst.", completion = "Well, I did warn you - did I not? Hopefully this payment more than makes up for the mild discomfort that you may have suffered. Return to me when you have gained strength and perhaps I will have another job for you - mushrooms of course!", sourceObjectiveStatus = "unverified-source-field" }
quests[9649] = { id = 9649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ysera's Tears", description = "Good to see you again, {name}! You were exceptionally efficient in completing the last task that I offered you. Perhaps you would be interested in another?\n\nTo the northeast lies Wyrmscar Island, home to a rare species of mushroom known as Ysera's tear - named after the green dragonlings that inhabit the island. I only require a small sampling of the mushroom, but I must warn you that the denizens of the island do not welcome visitors. Tread carefully.", sourceObjective = "Maatparm at Blood Watch wants 2 Ysera's Tears.", progress = "Back so soon?", completion = "I hope this wasn't too strenuous a task, {name}. Once again you have proven yourself a competent and considerate {race}. I offer my gratitude and a small bit of monetary compensation.", sourceObjectiveStatus = "unverified-source-field" }
quests[9663] = { id = 9663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Kessel Run", description = "You're just in time, {name}. Blood elf activity in this area has doubled in the past week. Our agents have informed us that the blood elves that call themselves Sunhawks plan to launch an offensive upon Azuremyst soon. I need you to get a warning out to our allies and compatriots.\n\nWarn High Chief Stillpine at Stillpine Hold, Exarch Menelaous at Azure Watch and Admiral Odesyus at Odesyus' Landing.\n\nTime is of the essence so I am lending you my elekk. Be sure to keep it out of water.", sourceObjective = "Kessel at Kessel's Crossing wants you to warn High Chief Stillpine at Stillpine Hold, Exarch Menelaous at Azure Watch and Admiral Odesyus at Odesyus' Landing of the imminent blood elf invasion. Return to Kessel when you complete this task. You have 15 minutes. (Be sure to keep it out of water.)", progress = "This is no time to relax!", completion = "Well done, {name}. This was a difficult test of your abilities, but you have passed with flying colors. To become a soldier of the Hand of Argus, you must pass many such tests.", sourceObjectiveStatus = "unverified-source-field" }
quests[9664] = { id = 9664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Establishing New Outposts", description = "Welcome to the Plaguelands, {name}. As you know, the Forsaken and their allies hold the lands to the west of here against our best efforts. The Alliance commanders have decided that here in the east, we will establish new fortifications to tighten the noose around our enemies.\n\nTowers long abandoned since the days of Lordaeron are to be seized and rebuilt for this purpose. These lands are dangerous, and we could use your help.", sourceObjective = "Capture Crown Guard Tower, Eastwall Tower, Northpass Tower and Plaguewood Tower in the Eastern Plaguelands, then return to Emmisary Whitebeard at Light's Hope Chapel.", completion = "Very good, {name}. It will be important for us to hold these towers against future attacks, and for that we may need your assistance until reinforcements can be brought in to secure the area.", sourceObjectiveStatus = "unverified-source-field" }
quests[9665] = { id = 9665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bolstering Our Defenses", description = "Agents of the Forsaken uncovered an Alliance plot to establish new bases here in the Eastern Plaguelands, at abandoned towers throughout the area.\n\nIt is imperative that we not allow them to establish a significant presence on our eastern borders, and so we must stave off this Alliance incursion. Our current plans are to drive them out of any towers they may have already seized, and occupy those that we have under our control against further attacks.", sourceObjective = "Capture Crown Guard Tower, Eastwall Tower, Northpass Tower and Plaguewood Tower in the Eastern Plaguelands, then return to Emmisary Gormok at Light's Hope Chapel.", completion = "This is good news, {name}. It will be a constant struggle here in the Plaguelands until we have fully driven back the forces of the Alliance.\n\nUntil that day, I hope that we will have your continued assistance.", sourceObjectiveStatus = "unverified-source-field" }
quests[9666] = { id = 9666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Declaration of Power", description = "Have you seen the serpent men? The ones that call themselves naga?\n\n<Kessel spits.>\n\nThey dared make an advance upon this camp under cover of darkness only three nights ago. Can you believe the audacity of those primitive beasts?\n\nI need you to deliver a message to their leadership, {name}. To the northeast is Wrathscale Lair, home to Lord Xiz. Find him, slay him where he stands and drive this banner through his corpse.\n\nLet them know fear whenever they should see our standard!", sourceObjective = "Kessel at Kessel's Crossing on Bloodmyst Isle wants you to kill Lord Xiz at Wrathscale Lair and drive the Draenei Banner through his dead body.", progress = "Is it done?", completion = "I am sorry that you had to do that, {name}. Heavy-handed violence is not the {race} way, but sometimes it is the only way.\n\nThis is one of life's truths that many do not understand until it is too late. So it was for our people, when we were slaughtered at the hands of the orcs.\n\nBecoming a Hand of Argus is a process of rebirth. And with birth comes pain...", sourceObjectiveStatus = "unverified-source-field" }
quests[9667] = { id = 9667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving Princess Stillpine", description = "Help me, {name}! The Bristlelimb captured me and are planning to sacrifice me to their foul gods!\n\nHigh Chief Bristlelimb holds the key that opens the cage. To force him to appear, you must slaughter the evil Bristlelimb furbolgs that inhabit the enclave, just two camps to the west of this camp. If you kill enough of them, he will surely come for vengeance! When he shows up, kill him and get the key!\n\nMy father will richly reward you if you can save me!", sourceObjective = "Release Princess Stillpine from her cage and then speak with Stillpine Ambassador Olorg at Blood Watch.\n\nYou must kill High Chief Bristlelimb for the key that opens the cage.", completion = "Once again you have proven yourself to be all that was prophesied. You have the eternal gratitude of the high chief {name} -- and these Stillpine relics to choose from...", sourceObjectiveStatus = "unverified-source-field" }
quests[9668] = { id = 9668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Exarch Admetius", description = "A Hand of Argus soldier is many things: Obedient, brave, intelligent, and above all, honorable. You may yet exhibit some of these traits, {class}.\n\nReport to Exarch Admetius at Blood Watch if you are still interested in joining the Hand. He and his subordinates will further train you in the ways of the draenei soldier.\n\nAnd remember this, {name}: Honorable people do not always perform honorably. Sometimes they cannot.\n\nYou will find Blood Watch just up this road, to the north.", sourceObjective = "Speak with Exarch Admetius at Blood Watch.", completion = "I had a feeling that you would make it this far, {class}. If you are willing to go further, I am willing to teach you...", sourceObjectiveStatus = "unverified-source-field" }
quests[9669] = { id = 9669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Expedition", description = "About a week ago, my research team and I were out exploring the western wilds of Bloodmyst when we were attacked by bloodthirsty spiders. The effect of the crystal contamination was clearly evident as these spiders were massive and extremely aggressive.\n\nI managed to escape but my team wasn't so lucky. We must not let the same fate befall others. Go west to the Amberweb Pass and destroy the spiders and their matriarch, Zarakh.", sourceObjective = "Kill 8 Myst Spinners, 8 Myst Leechers and their leader, Zarakh. Return to Achelus at Blood Watch when the task is complete.", completion = "Incredible! Did you find any survivors?\n\n<Achelus lowers his voice to a whisper.>\n\nI'll be honest, {name}; nobody else was willing to take on this mission. You are a brave {class}...", sourceObjectiveStatus = "unverified-source-field" }
quests[9670] = { id = 9670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They're Alive! Maybe...", description = "It was a bloody mess, {name}. We were ambushed by a large pack of these spiders. Their progenitor descended upon us with incredible speed and wrapped us up in cocoons.\n\nAfter we were webbed, she began to lay eggs near us. We were to be food for her young! FOOD!\n\nI managed to cut my way out and escape but I will not leave the others behind. So far I've been unsuccessful in nearing the pass. Would you lend a hand?\n\nDestroy those cocoons! Hopefully some of our team is still alive!", sourceObjective = "Researcher Cornelius has asked that you free 5 Expedition Researchers.", progress = "Any luck?", completion = "You rescued over half the team! Word of your deed will definitely get back to Blood Watch and the exarch. Thanks again, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9671] = { id = 9671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urgent Delivery", sourceObjective = "Are you {name}? It's about time! I'd just about given up on finding you!\n\nThere's an urgent message waiting for you at the mailbox. The person that gave it to me was a human admiral from Azuremyst. Admiral Odesy-something... the name escapes me. He said you would know who he was.", sourceObjectiveStatus = "unverified-source-field" }
quests[9672] = { id = 9672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bloodcurse Legacy", description = "Dear friend,\n\nMy hand trembles as I ink this letter. I pray that it reaches you in time.\n\nLast night, Edward Hanes, captain of the ship 'Lost Hope', appeared before me in my tent. The same Edward Hanes that died of scurvy 20 years ago.\n\nThis apparition told me a tale that made my heart tremble. A tale that I need you to hear and a mission that I need you to accomplish. Will you do it? Will you seek out Edward on Wyrmscar Island, northeast of your base?\n\nRegards,\n\nAdmiral Odesyus", sourceObjective = "Admiral Odesyus has asked that you find and speak with Captain Edward Hanes.", completion = "Have you heard of the bloodcurse, landlubber? No, of course you haven't. The bloodcurse is what sunk all these ships. The spoiled, desecrated part of the water here is known as Bloodcursed Reef - a part of the world you never want to visit. I've been here myself for 20 years.\n\nScurvy my foot! I died on these wild shores as food for the dragons... Ah, but that's another story for another time. Right now, we have to help the poor souls that are trapped in that reef.", sourceObjectiveStatus = "unverified-source-field" }
quests[9673] = { id = 9673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beast Training", description = "Beyond bonding with your chosen pet, there remains the intricacies of caring and training it.  For this, Halthenis the beast trainer of Silvermoon City can show you the way.\n\nHe always shows the utmost respect for my students, if they do the same for him.  Do not disappoint me.", sourceObjective = "Speak with Halthenis in Silvermoon City.", completion = "So you've learned a bit, have you?\n\n<Halthenis looks at you carefully.>\n\nYou'll serve the city, and our greater cause, well with your newly-learned skills.  Allow me a moment to show you how to train your pet to do some interesting tricks, like disemboweling your enemy, and you can be on your way.", sourceObjectiveStatus = "unverified-source-field" }
quests[9674] = { id = 9674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bloodcursed Naga", description = "They say when the world was sundered, this land cried the loudest. It was here that thousands of night elves faded into oblivion and in their place rose terrible creatures of hate - the naga.\n\nObedient to their twisted queen, Azshara, they would destroy all that would dare pass through their sea. It would remain this way for thousands of years - until now.\n\nThe first order of business is to remove the bloodcursed naga from the reef.", sourceObjective = "Captain Edward Hanes on Wyrmscar Island wants you to kill 10 Bloodcursed Naga.", progress = "They're nasty creatures...", completion = "A good start, but there's much more to be done!", sourceObjectiveStatus = "unverified-source-field" }
quests[9675] = { id = 9675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beast Training", description = "Oh, one more thing!  You'll want to speak with Ganaar at the Exodar.  He'll be able to teach you the last bits of knowledge necessary to care for your pet and train it.\n\nYou can find him in the southwest corner of the Traders Tier.", sourceObjective = "Speak with Ganaar at the Traders Tier of the Exodar.", completion = "Knowing how to feed and revive your pet from death is not just an extra \"tidbit\" as your last teacher so mildly put it.  Even more so, training allows your pet to improve in ways they couldn't have on their own.\n\nI've already learned much from the furbolgs, so pay attention and I'll pass the knowledge on to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[9676] = { id = 9676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paladin Training", description = "As you advance within your class, you will want to take advantage of the training that your class trainer can provide you.  For young paladins here on Sunstrider Isle, your trainer is Jesthenis Sunstriker. Speak with Jesthenis and see what training he has available for you.  The things he will teach do have a cost, so bring some coin with you.\n\nYour trainer - as with all the trainers on Sunstrider Isle - is inside the Sunspire on the lower level.", sourceObjective = "Speak with Jesthenis Sunstriker - the Paladin class trainer - inside the Sunspire on Sunstrider Isle.", completion = "I see the pride swelling in your chest. Already you fancy yourself one of the Blood Knights.\n\nIn time, you will earn your place among us. But first you must learn to harness and master the powers of the Light, hone your skills at arms, and prove your worthiness.\n\nYou must be prepared to endure the derision, fear, and revulsion of those you're sworn to defend. So it is among those who can't comprehend the price of the great power that safeguards them. Keep your head high and your blade at the ready, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9677] = { id = 9677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Summons from Knight-Lord Bloodvalor", description = "{name}, you have excelled in your early training and distinguished yourself among those who would become Blood Knights. You are ready to undertake the next phase of your training and, to that end, Knight-Lord Bloodvalor himself has asked to speak with you.\n\nI have no doubt that Knight-Lord Bloodvalor wishes to set a trial for you to test your abilities and training. You will find him in the Blood Knight headquarters in Silvermoon City's Farstriders' Square. I wish you well, {name}.", sourceObjective = "Speak with Knight-Lord Bloodvalor in Farstriders' Square in Silvermoon City.", completion = "Welcome, young initiate. That you have answered my summons so promptly bodes well for you.\n\nLet us dispense with pleasantries, then, as they are best left to courtiers and their ilk.\n\nYour rapid progress has caught my attention, {name}. We will see if you have taken your lessons to heart.", sourceObjectiveStatus = "unverified-source-field" }
quests[9678] = { id = 9678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The First Trial", description = "You have learned much of combat and bloodshed, initiate, but there is much more to our order.\n\nMastery of the Light requires a focused mind and tremendous willpower. Without these, you are little better than a street thug.\n\nThere is an island in the northeastern reaches of the Ghostlands, called the Isle of Tribulations, that we use to hone these skills. You will find a brazier within a shallow cave there. Kneel before the brazier, light it, and focus on what you see before your eyes.", sourceObjective = "Travel to the island Knight-Lord Bloodvalor described, find the cave, and light the brazier. When the First Trial is over, return to Knight-Lord Bloodvalor in Silvermoon City.", progress = "May the Light bend to your will in all endeavors.", completion = "I know what must be going through your mind.\n\nYes, I sent Stillblade to kill you.\n\nDo not take offense, {name}; it was a necessary test. The Blood Knights are a brotherhood, but we must ensure that our brothers are alert and prepared at all times. Was it necessary to take Stillblade's life to make the point to you?\n\nYes, and that is as much a part of your training as any sword drill.", sourceObjectiveStatus = "unverified-source-field" }
quests[9680] = { id = 9680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Digging Up the Past", description = "Kamsis was right!  This information is extremely important.\n\nIf Medivh weaved his own essence into the magic he used to defeat the dragon, it is quite possible we could retrieve even a faint residue of that essence from the dragon's remains.  What great insight may lie beneath the ashes of Deadwind Pass, awaiting discovery.\n\nGo to the mountains south of Karazhan and bring me back a bone fragment of seemingly draconic origin.", sourceObjective = "Archmage Alturus wants you to go to the mountains south of Karazhan in Deadwind Pass and retrieve a Charred Bone Fragment.", progress = "Have you retrieved the bone fragment I require, {name}?", completion = "Excellent!  Though small in size, this fragment is teeming with energy, I can feel it!", sourceObjectiveStatus = "unverified-source-field" }
quests[9681] = { id = 9681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Study in Power", description = "Do not think me unduly harsh, {name}. Stillblade knew well what he was being sent to do. He understood and accepted his duty and is an example for all aspiring Blood Knights.\n\nMy words are no eulogy, {name}. Stillblade's service to us is far from over and you will be the instrument of his resurrection.\n\nYour education in the order's ways has just begun. With the betrayal of Kael'thas and the loss of our power source, you must learn new methods of wielding the Light. Seek out Magister Astalor Bloodsworn.", sourceObjective = "Speak with Magister Astalor Bloodsworn in the hidden chamber beneath Blood Knight headquarters.", completion = "Welcome, young {class}.\n\nAt the order's founding, Kael'thas gifted us with a captured naaru, a being of the very Light we wield. Through our superior magical abilities, we learned to control and subdue it, allowing the Blood Knights to draw power from it.\n\nKael'thas' own lust for power got the better of him, though, and he allied with our enemies. His vile followers attacked us, taking the naaru, and cutting us off from the source. These are dark days for the order, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9682] = { id = 9682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hopeless Ones...", description = "On a ledge of the reef, deeper than where you found the bloodcursed naga, you will find the hopeless ones: The bloodcursed voyagers, ghosts of those taken by the bloodcurse.\n\nIt is regrettable, what I ask of you now... but they must be destroyed and their cursed shells brought back to me.\n\nTheir souls must be put to rest. Return to me when you have done as asked and I shall give you one final task.", sourceObjective = "Captain Edward Hanes on Wyrmscar Island wants you to recover 4 Bloodcursed Souls.", progress = "Do not mourn their demise, {name}.", completion = "You have done the hopeless ones a great service, {name}. There is but one final task: Destroy the leader of the Bloodcursed.", sourceObjectiveStatus = "unverified-source-field" }
quests[9683] = { id = 9683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ending the Bloodcurse", description = "To the south you will find Bloodcurse Isle. Atop the island you will find a shrine dedicated to the beloved queen of the naga, Azshara. Destroy the statue - burn it in effigy! This will surely draw the ire of Atoph, the Bloodcursed leader.\n\nSlay Atoph and return to me!", sourceObjective = "Captain Edward Hanes on Wyrmscar Island wants you to destroy the Statue of Queen Azshara and kill Atoph the Bloodcursed.", progress = "Atoph must be lured out!", completion = "You did it! Hundreds of souls are grateful for all that you have done.\n\nAllow me to make an offering...", sourceObjectiveStatus = "unverified-source-field" }
quests[9684] = { id = 9684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Claiming the Light", description = "Take this vessel, {name}. The enchantment it bears will allow you to draw the last vestiges of the Light surrounding these magisters. They once tended the captive naaru and some of its energy yet remains within them.\n\nIt will be just enough to restore your comrade to life.\n\nDo not worry about the magisters, {name}. I have seen to their care, and Lord Solanar assures me that Lady Liadrin seeks a new source of power even now.", sourceObjective = "Use the Shimmering Vessel on the Blood Elf Magisters to fill it and return to Knight-Lord Bloodvalor in Silvermoon City.", progress = "Have you spoken with Magister Astalor Bloodsworn?", completion = "Well done, {name}. The powers granted by the Light have never come 'naturally' to the Blood Knights, but we are not so weak-willed as to let nature dictate to us.\n\nOur mastery of the arcane has provided a path to help see us through these harsh times. Power no longer flows freely in these halls, but it is there for the tenacious and strong of will. Few have the stomach or the aptitude to master it these days, but I know you will not disappoint the order.", sourceObjectiveStatus = "unverified-source-field" }
quests[9685] = { id = 9685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Redeeming the Dead", description = "While you were preparing the vessel, I sent a group of initiates to retrieve Sangrias Stillblade. You will find him on the top level of Silvermoon's inn with an attendant. Make your way there with all haste and unleash the vessel's magic to restore him to life.\n\nTime is of the essence, {name}. Once he has been dead for too long, not even the Light can bring him back to us. Return to me once you have resurrected Stillblade.", sourceObjective = "Take the Filled Shimmering Vessel to Silvermoon City's inn and use its magic to resurrect Sangrias Stillblade.", completion = "Welcome back, initiate. Now that you know the truth about the source of our power and you have demonstrated your skill in wielding it, I will grant you the ability to resurrect the fallen in the field.\n\nStay true to the order and excel at your training and you will only continue to grow in power.", sourceObjectiveStatus = "unverified-source-field" }
quests[9686] = { id = 9686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Second Trial", description = "You stand on the verge of adept status in the order, {name}. First, you must prove your worthiness by undertaking another trial.\n\nThe Second Trial differs from the first in that there will be no surprises this time. The challenge before you is simple; you must face and best four Blood Knight champions in combat.\n\nWhen you accept the challenge, a crystal will appear in the middle of the pavilion. Touch it to begin your trial and do not stray far from the building.\n\nAre you prepared?", sourceObjective = "Complete the Second Trial by defeating Champion Bloodwrath, Champion Lightrend, Champion Swiftblade, and Champion Sunstriker in the pavilion near Master Kelerun Bloodmourn.", progress = "A Blood Knight would rather die than submit to the enemy. Remember that, {name}.", completion = "Well done, {name}! You have proven yourself worthy of full membership in the Blood Knights and elevation to adept status. However, there are a few more tasks that remain before your induction can take place.", sourceObjectiveStatus = "unverified-source-field" }
quests[9687] = { id = 9687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restoring Sanctity", description = "Not long ago, the once tranquil owlkin of the region appeared on the shores of this island. One by one they would come to steal the bones of the fallen dragons. I do not know what would cause these creatures such distress or why they would want the bones of the deceased, but the spirits of the brood have grown restless due to this sacrilege.\n\nTo the west, across the Crimson Reach, you will find Ragefeather Ridge. Venture to the owlkin encampments and recover the pilfered dragon bones.", sourceObjective = "Prince Toreth on Wyrmscar Island wants you to recover 8 Dragon Bones.", progress = "The dragon wars have long since passed. All that remains are bones and the agitated remnants of Ysera's brood.", completion = "A ritual? The owlkin had lived in harmony with the land for thousands of years. Such a thing is an aberration!\n\nSuch a pity...", sourceObjectiveStatus = "unverified-source-field" }
quests[9688] = { id = 9688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Dream", description = "The whelps that you see on this island are the agitated spirits of the green dragonflight. Like me, they are bound to the land, unable to ascend to their final resting place in the Dream.\n\nRecovering the bones of the fallen has settled them somewhat but you must take further action.\n\nDestroy their ethereal manifestations. I cannot leave this place until it is done. They must be released!", sourceObjective = "Prince Toreth at Wyrmscar Island has asked that you slay 5 Viridian Whelps and 5 Viridian Broodlings.", progress = "It pains me to watch. Please, let us not speak of this any further.", completion = "As reprehensible as your task was, it had to be done. Now you must look into the face of evil.", sourceObjectiveStatus = "unverified-source-field" }
quests[9689] = { id = 9689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Razormaw", description = "Many of the black dragonflight were slain during the attacks. One of them, a lieutenant of Deathwing himself, still haunts this place. If you look to the heavens, you can see his spectral countenance circling the skies. His hatred is so great that he remains even in death.\n\nTake the bones that you gathered for me earlier to the top of the mountain on this island and place them in the ever-burning pyre. This act should signal Razormaw to descend. When he does, slay his undead form.", sourceObjective = "Prince Toreth at Wyrmscar Island has asked that you slay Razormaw.", progress = "I recommend that you bring allies, {name}.", completion = "How long has it been? A thousand years? Ten-thousand perhaps? You have done me and the memory of my people a great service, {name}. Please accept this item of power as a token of appreciation from Loreth'Aran - in honor of your deeds.", sourceObjectiveStatus = "unverified-source-field" }
quests[9690] = { id = 9690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Second Trial", description = "Initiate {name}, you have worked hard to master the powers of the Light won by our magisters. You have learned the source of our abilities and of the duties of a Blood Knight.\n\nThe time has come for you to undergo the Second Trial, and contest for status as an adept among the Blood Knights. The trial will be administered by Master Kelerun Bloodmourn at a location north of the city. Travel north through the Ruins of Silvermoon and take the east path immediately before the bridge to Sunstrider Isle.", sourceObjective = "Report to Master Kelerun Bloodmourn.", completion = "When you are ready, I will tell you more about the trial you are to undergo. Make your preparations and speak to me again when you wish to begin.", sourceObjectiveStatus = "unverified-source-field" }
quests[9691] = { id = 9691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Silvermoon", description = "Return to Silvermoon City and report to Knight-Lord Bloodvalor promptly. Your arrival will tell him all he needs to know about the outcome of the trial.\n\nHe will tell you of your remaining tasks on the road to becoming an adept. Hold your head high, {name}. Many undertake this trial, but very few return to tell of their success.", sourceObjective = "Return to Knight-Lord Bloodvalor in Silvermoon City.", completion = "I knew you had the potential to pass the trial, {name}. Your remaining duties are mostly ceremonial, but they are no less dangerous than staring down one of our champions with his weapon drawn. Listen closely, and I will tell you what else you must do to claim your new rank.", sourceObjectiveStatus = "unverified-source-field" }
quests[9692] = { id = 9692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path of the Adept", description = "Before a newly-minted adept can be accepted into the ranks of the Blood Knights, <he/she> must procure the resources  to create our order's distinctive weapon, the blood-tempered ranseur.\n\nYou must also earn the right to wear our order's insignia. When the order was founded, a set number were forged and distributed, so each new adept inherits <his/hers> from a veteran. Your insignia will come from a fallen knight who bravely led an assault on Deatholme.\n\nI have prepared a set of notes to guide you.", sourceObjective = "Bring a Corrupted Kor Gem, a Crate of Bloodforged Ingots, a quantity of Blood of the Wrathful, and a Blood Knight Insignia to Knight-Lord Bloodvalor in Silvermoon City.", progress = "Have you done all that was asked of you?", completion = "Excellent, {name}. It's all here. All that remains is to forge the weapon.", sourceObjectiveStatus = "unverified-source-field" }
quests[9693] = { id = 9693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Argus Means to Me", description = "What does Argus mean to you, {name}? Many draenei probably do not know or remember our home planet. It is there that we split from the man'ari: the twisted demonic reflections of ourselves that were 'gifted' by Sargeras. Or as they call themselves, eredar.\n\nEredar... this word once held meaning.\n\n<Admetius smacks his lips as if to taste the word.>\n\nDisgusting.\n\nLet us not waste anymore time. Find Vindicator Boros to begin your training.", sourceObjective = "Exarch Admetius at Blood Watch has told you to speak with Vindicator Boros.", completion = "Ah, {name}... I've heard about you. You're the one that made the Kessel Run in under 15 minutes, right? Bah, probably not.\n\nAre you ready to spill some blood in the name of the Light? For Velen? For Argus?\n\n\n\nI'll slow down.", sourceObjectiveStatus = "unverified-source-field" }
quests[9694] = { id = 9694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Watch", description = "Blood Watch is one of two forward bases operated by the Hand of Argus. You have already been to the other base, Azure Watch; things are completely different in Bloodmyst. When we first got here, the land was as beautiful as Azuremyst. We even called it Silvergale but now sickness is spreading across the land, worse yet, the blood elves that we were battling on the Exodar survived the crash. This brings me to your assignment: Venture northwest into Bladewood and terminate any blood elves that you find.", sourceObjective = "Vindicator Boros at Blood Watch wants you to slay 10 Sunhawk Spies.", completion = "You have returned - and in one piece!\n\nI have some good news, {name}. We have received some new information about the possible location of more survivors. A new crash site has been discovered! When I am done attending to those matters, I will call for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[9695] = { id = 9695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sun King's Command", description = "This document looks to be important. Unfortunately, it is written in Thalassian, a language that you cannot understand.\n\nPerhaps Vindicator Boros will know what to do with the letter.", sourceObjective = "Take the Sun King's Command to Vindicator Boros at Blood Watch.", sourceObjectiveStatus = "unverified-source-field" }
quests[9696] = { id = 9696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Translations...", description = "Our chief interrogator, Elysia, is fluent in Thalassian. Take the document to her and see what she has to say.", sourceObjective = "Take the Sunhawk Missive to Interrogator Elysia at Blood Watch.", progress = "I'm a bit busy here, agent {name}. This better be important.", completion = "<Elysia reads from the document.>\n\nIf what this document says is true, the blood elves have opened a portal to the Outland! It would certainly explain their seemingly endless numbers...", sourceObjectiveStatus = "unverified-source-field" }
quests[9697] = { id = 9697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Watcher Leesa'oh", description = "There's important research to be conducted into the ecology of the local creatures, especially the sporelings and bog lords of the marsh.  And trust me, once you get out into the field, you'll find the work to be challenging.\n\nSeek out Watcher Leesa'oh at the Cenarion Watchpost in the western region of the marsh toward the south.  Follow the path west and you will eventually find her.  She can be a bit -- studious -- but don't let that get to you.\n\nOh, and watch out for her cat.", sourceObjective = "Speak with Watcher Leesa'oh at the Cenarion Watchpost in Zangarmarsh.", completion = "Oh, good... help finally!  There's just so much to do, and I need to stay here to organize it all.\n\nI hope that you're ready to get your hands dirty.", sourceObjectiveStatus = "unverified-source-field" }
quests[9698] = { id = 9698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Audience with the Prophet", description = "I need you to deliver the translated documents to Velen personally, {name}. I don't trust that deranged messenger.\n\nExplain to the Prophet that the blood elves are receiving reinforcements from the Outland and that they have a spy amongst the draenei at the Exodar. Velen resides in the Vault of Lights inside the Exodar.\n\nMake haste!", sourceObjective = "Take the Translated Sunhawk Missive to Prophet Velen at the Exodar.", progress = "<Velen smiles.>\n\nGreetings, {name}. I have been expecting you.", completion = "<Velen begins to read the document.>\n\nInteresting... This does indeed explain much.", sourceObjectiveStatus = "unverified-source-field" }
quests[9699] = { id = 9699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Truth or Fiction", description = "I thank you for the timely delivery, {name}. You are turning out to be one of the Hand's better agents.\n\nIf only we knew who they reported to in Bloodmyst and more importantly, where this sun portal was... They seem to have it tightly guarded - wherever it may be.\n\nWould you be interested in some reconnaissance work?\n\nIf so, take these orders back to Vindicator Boros. He will give you your next mission.", sourceObjective = "Take Velen's Orders to Vindicator Boros at Blood Watch.", progress = "Well?", completion = "It's a good plan, but a dangerous one. I'm sure you'll be fine.", sourceObjectiveStatus = "unverified-source-field" }
quests[9700] = { id = 9700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Shoot Magic Into the Darkness", description = "Velen states that if the blood elves have been opening rifts between this island and the Outland, there will be residue or anomalies left in the areas where the portals have been opened. You must search the island for locations that exhibit or display these anomalies.\n\nBe warned, {name}; some of these anomalies will be creatures from the void itself. Should you find void anomalies, slay them! Report back to me with any new information that you may find. Begin your search to the north, near the Warp Piston.", sourceObjective = "Vindicator Boros at Blood Watch wants you to locate the Sun Portal Site and slay 5 Void Anomalies.", progress = "I've been hearing reports of strange creatures appearing in the area. Whether they are mutated indigenous animals or true void anomalies is something that you need to find out.", completion = "How many did you say you saw at the Warp Piston? Just how many times have they opened up this sun portal? This is very bad news...\n\nAlas, you have learned all that I am able to teach you, {name}. Kuros will call for you when it is time.", sourceObjectiveStatus = "unverified-source-field" }
quests[9701] = { id = 9701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Observing the Sporelings", description = "We need to learn all that we can of the sporelings at Sporeggar and their relationship to the creatures around them.  One way to do that is what I'm doing; passive observation while making a note of their interactions.\n\nI need you to head over to the Spawning Glen to the west.  Investigate the whole area and then return to tell me what you saw.", sourceObjective = "Investigate the Spawning Glen in Zangarmarsh, and then report back to Watcher Leesa'oh at the Cenarion Watchpost in Zangarmarsh with your findings.", progress = "Back so soon?  Your observation of the Sporeggar sporelings is critical to my research.  I hope you aren't the type to rush things.  Show patience and make certain that you have explored the entirety of the Spawning Glen before giving me your final report.", completion = "What?!  The bog lords of Quagg Ridge are EATING the sporelings' pods?  This isn't good!", sourceObjectiveStatus = "unverified-source-field" }
quests[9702] = { id = 9702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Question of Gluttony", description = "I was wondering why the bog lords were crossing the road to go to the Spawning Glen - they must be starving for some reason.  This just will not do!\n\nI mean, normally I wouldn't get involved, but if they continue to eat all of the sporeling pods they'll wipe them out!\n\nHere's what we'll do: I'll stay here and you head to the Quagg Ridge to the east and look for dietary clues as to why they're raiding the sporelings.", sourceObjective = "Collect 10 pieces of Discarded Nutriment and then return to Watcher Leesa'oh at the Cenarion Watchpost in Zangarmarsh.", progress = "Be sure that you collect all of the evidence carefully, {class}!  We're fitting the pieces of a giant puzzle together here.  A mistake on your part could lead us to the wrong conclusions.\n\nThen where would we be in our understanding of Zangarmarsh's ecology?", completion = "This is what you found?  That's odd.  These husked mushroom remains are both unusual and somehow look familiar.\n\nI have to think on this a moment.  Don't go anywhere!", sourceObjectiveStatus = "unverified-source-field" }
quests[9703] = { id = 9703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cryo-Core", description = "We have others pursuing leads on the sun portals, {name}. I need you to focus on the task at hand.\n\nBoros has received new reports of another crash site. What we've since discovered is that the crash site is actually the Exodar's cryo-core. This is a pod holding area that houses pods exactly like the ones we draenei crawled out of in Ammen Vale.\n\nThis area also holds medical supplies. Head to the Cryo-Core, directly west of Blood Watch. Search for supplies and search for survivors.", sourceObjective = "Vindicator Kuros at Blood Watch wants you to recover 12 boxes of Medical Supplies.", progress = "Was the information accurate?", completion = "Just blood elves? No survivors? This is troubling. I'll need some time to think this through, {name}. Perhaps Aesom or Boros have an assignment for you to complete.", sourceObjectiveStatus = "unverified-source-field" }
quests[9704] = { id = 9704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slain by the Wretched", description = "It's hard work being an outrunner between Sunstrider Isle and Falconwing Square.  Tight deadlines, long hours and worst of all... the Wretched!\n\nThe road south goes through the ruins of Silvermoon... the place is crawling with Wretched ready to kill you for a few mana crystals.  Unfortunately, I think that's what happened to the last outrunner we sent with one of Erona's packages.\n\nI see you're eager to prove yourself.  Venture into Dawning Lane and see if you can find any traces of our outrunner.", sourceObjective = "Go south into the ruins of Silvermoon and look for the Slain Outrunner in Dawning Lane.", completion = "The outrunner's belongings have all been stolen with the exception of one package.  It seems to match Alarion's description of Erona's package.", sourceObjectiveStatus = "unverified-source-field" }
quests[9705] = { id = 9705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Package Recovery", description = "You take the package and confirm that indeed it comes from Magistrix Erona.  Alarion would probably want you to bring it to her.", sourceObjective = "Return to Outrunner Alarion with Erona's Package.", progress = "What did you find, {name}?", completion = "By the Sunwell!  That's the third outrunner we've lost this month.\n\nI appreciate your courage in venturing into Dawning Street.  The guards need to keep a closer eye on these blasted Wretched.", sourceObjectiveStatus = "unverified-source-field" }
quests[9706] = { id = 9706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Galaen's Journal - The Fate of Vindicator Saruan", description = "Your hands tremble as you pick up the book. Kuros must be told about this tragedy. Return the book to him.", sourceObjective = "Take Galaen's Journal to Vindicator Kuros at Blood Watch.", progress = "What have you got there, {name}? Is that a journal?", completion = "<Kuros' face turns pale as he reads the journal; tears stream down his face.>\n\nSaruan was my master... my teacher... my mentor... I took his place among the Triumvirate only recently - after we had given up searching for him.\n\n<Kuros' face contorts in anger.>\n\nMatis...", sourceObjectiveStatus = "unverified-source-field" }
quests[9707] = { id = 9707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forging the Weapon", description = "Once again, you have proven yourself worthy before the order and your peers. It is with great pleasure that I bestow upon you the rank of adept, {name}. Prince Kael'thas himself would be proud of you.\n\nAny of us would be honored to fight by your side on the field of battle. Continue to serve as an example for those who aspire to join us. Show neither mercy nor weakness, defend your people and your brothers tirelessly, and hone your mastery of the Light.\n\nNow, claim the weapon befitting your new rank.", sourceObjective = "Take the Crate of Materials to Bemarrin in Silvermoon City.", progress = "Congratulations, {name}. Achieving the rank of adept is no mean feat, believe me. I've seen the number of people who enter that building, and how few of them last long enough to visit me bearing these materials.", completion = "It looks like you've got everything I'll need. Let's get started!", sourceObjectiveStatus = "unverified-source-field" }
quests[9708] = { id = 9708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Familiar Fungi", description = "Yes, that's it, I knew I had seen this particular phylum of mushroom elsewhere in the marsh!\n\nTo the north is a place known as the Hewn Bog.  Odd name for the place if you ask me, but I've never been there.  I'll need samples of those mushrooms to confirm my hypothesis.\n\nJust be careful, {class}.  I'd heard that ogres have moved in to the area, so you'll have to get the samples from them.  Could that be why the bog lords are no longer going there for their food?", sourceObjective = "Collect 15 Mushroom Samples and return them to Watcher Leesa'oh at the Cenarion Watchpost in Zangarmarsh.", progress = "Do you have those samples yet?", completion = "We definitely have a match here.  And the presence of the ogres and what they were doing there explains everything.  Now I get why it's called the Hewn Bog, duh!\n\nWe have to do something about this situation, but what?  We can't just wipe out all of those ogres; they have every bit as much a right to be here as any of the other creatures in the marsh!", sourceObjectiveStatus = "unverified-source-field" }
quests[9709] = { id = 9709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing Back the Mushrooms", description = "{class}, I've got an idea.   I want you to head north again, this time into the heart of ogre territory!\n\nNorthwest of the Hewn Bog there is a place named Ango'rosh Stronghold, which sits on a floating island across a large mushroom bridge.\n\nThe ogres must be storing the harvested mushrooms there.  I bet you'll find them all over the place, and probably on the ogres themselves, too!\n\nBring me a sufficient number and I will try to do something about providing the bog lords with a new source of nourishment.", sourceObjective = "Collect 10 Boxes of Mushrooms and return them to Watcher Leesa'oh at the Cenarion Watchpost in Zangarmarsh.", progress = "You have all of the mushrooms that we need to create a new garden for the bog lords?", completion = "These are perfect!  Oh, thank you, {class}!\n\nYou've been ever so careful not to disturb the natural order of things, and we've gathered so much information in such a short amount of time!\n\nNow, let's see if our little plan to grow a new food supply for the bog lords is going to work.", sourceObjectiveStatus = "unverified-source-field" }
quests[9710] = { id = 9710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blood-Tempered Ranseur", description = "I've got everything prepared, {name}. Very soon you will have a weapon befitting your new status.", sourceObjective = "Wait while Bemarrin forges your weapon.", completion = "Here it is, {name}. Use it well in the service of Silvermoon and your order.", sourceObjectiveStatus = "unverified-source-field" }
quests[9711] = { id = 9711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Matis the Cruel", description = "Matis will be brought to justice, {name}; and I want you to be the one to find him and bring him back to the Triumvirate.\n\nScour the island for this killer. Should you find him, use this flare gun. When my trackers see the flare, they'll come and assist in capturing Matis. Return to me after he's been captured.", sourceObjective = "Vindicator Kuros at Blood Watch wants you to capture Matis the Cruel.", completion = "The Triumvirate has decided to try Matis immediately. You have brought an arch-criminal to justice on this day, young {race}.\n\nYou have performed admirably for two of three; only Aesom remains.", sourceObjectiveStatus = "unverified-source-field" }
quests[9712] = { id = 9712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Thalassian Warhorse", description = "You have distinguished yourself in the service of the order, {name}. Your skill in wielding the Light energies granted by Magister Astalor and his fellows has proven you worthy to receive a new kind of knowledge.\n\nWith the Light at your command, it is possible to summon a fearsome warhorse that will serve as your faithful mount.\n\nContinue to serve with dedication and honor, {name}, and even greater boons await you.You will learn:", sourceObjective = "Talk to Knight-Lord Bloodvalor to learn how to summon your Thalassian Warhorse.", sourceObjectiveStatus = "unverified-source-field" }
quests[9714] = { id = 9714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring Me Another Shrubbery!", progress = "We can still use more of the sanguine hibiscus from the shamblers, bog giants and underbats of the Underbog at Coilfang Reservoir.  Bring them to me in bunches of five and I will be most grateful.", completion = "These will do nicely, but we can always use more.  Perhaps you will find yourself in the Underbog again soon?" }
quests[9715] = { id = 9715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring Me A Shrubbery!", description = "We must replenish our supply of sanguine hibiscus, which we use for a number of purposes.  They used to grow thick as shrubs, but the lowering of the marsh's water levels means that they can only be found now in the Underbog at Coilfang Reservoir, under Serpent Lake.\n\nIt is said that the shamblers, bog giants, and underbats there consider them a delicacy.  So, if you are to help us, you must retrieve the flowers from them.", sourceObjective = "Collect 5 Sanguine Hibiscus and return them to Gzhun'tt at Sporeggar in Zangarmarsh.", progress = "Do you have all of the hibiscus that I asked you to gather?", completion = "These will do nicely, but we can always use more.  Perhaps you will find yourself in the Underbog again soon?", sourceObjectiveStatus = "unverified-source-field" }
quests[9716] = { id = 9716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disturbance at Umbrafen Lake", description = "We came to Outland expecting to find small pockets of life.  What we discovered in Zangarmarsh was a lush environment with a thriving ecosystem.\n\nOur initial assessment of the area was deceiving, however.  The water levels at the lakes and marshes have consistently been going down since we started taking measurements.\n\nThe impact this could have on the local animal and plant life is disastrous.  Go to Umbrafen Lake, southwest of here, and look for clues related to this water depletion.", sourceObjective = "Investigate the cause of the water depletion at Umbrafen Lake. Then return to Ysiel Windsinger at the Cenarion Refuge in Zangarmarsh.", progress = "Did you discover anything, {name}?", completion = "The naga are behind this!  But why?  From what you describe, that steam pump must be part of the cause for the water levels dropping in the marsh!\n\nNo matter - this explains their open hostility towards us.  Let's not waste any time, I need you to perform another task for us.", sourceObjectiveStatus = "unverified-source-field" }
quests[9717] = { id = 9717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh, It's On!", description = "While we are a peaceful people, we are at war with the spore giants, whether we like it or not.  And there is a saying amongst us that all is fair in mushrooms and war!\n\nOne of the leaders of the spore giants, Hungerfen, has been tending a very special plant, known as the Underspore, to perfection for millennia.  It would break his spirit if something were to happen to that plant.\n\nTravel to the Underbog in Coilfang Reservoir and steal a frond off of it for us.  Trust me, he'll notice.", sourceObjective = "Gather an Underspore Frond and return it to T'shu at Sporeggar in Zangarmarsh.", progress = "The Underbog is a very dangerous place.  I would not consider you a coward if you were to balk at going there.  I also wouldn't be appreciative of you if you did not return with what I've asked for.", completion = "<The sporeling makes a sound that is vaguely reminiscent of snorting laughter.>\n\nPerfect!  No doubt the morale of the spore giants will be at an all time low once they realize what you've done.\n\nEither that, or they'll be so incensed that they'll attack us again soon.\n\n<T'shu makes a shrugging motion.>", sourceObjectiveStatus = "unverified-source-field" }
quests[9718] = { id = 9718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "As the Crow Flies", description = "We must determine how widespread the naga's activity truly is and react accordingly.\n\nExploring each body of water in Zangarmarsh could be a lengthy undertaking.  If you allow me to, I will use my magic to mold your shape to one more suited to scouting the marsh.\n\nHold this amulet above the balcony near me when you're ready to begin.  I will guide your way back to safety after we're done.", sourceObjective = "Ysiel Windsinger wants you to use the Stormcrow Amulet to explore the major lakes in Zangarmarsh.", progress = "Hail, {name}.", completion = "It is as I suspected.  The naga have set up pumping stations at all the major lakes in Zangarmarsh. \n\nThey must be stopped if the marsh is to have a future.", sourceObjectiveStatus = "unverified-source-field" }
quests[9719] = { id = 9719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stalk the Stalker", description = "Historically the greatest danger to my people has been from the marsh walkers.  With the new problems we are facing from spore giants, we cannot afford another attack from our ancient enemies.\n\nYou have proven yourself to be capable, {class}.  Do you think that you'd be able to journey to the Underbog in Coilfang Reservoir and eliminate the great mother of the marsh walkers, known as The Black Stalker?!\n\nBring me her brain as proof.", sourceObjective = "Bring the Brain of the Black Stalker to Khn'nix at Sporeggar in Zangarmarsh.", progress = "You have returned.  Does this mean that The Black Stalker is no more?", completion = "The Black Stalker is dead!  Normally I would not revel in such butchery, but the pain that the great mother and her brood have put my people through over the centuries is unspeakable.\n\nIt is unfortunate that now another of her progeny will transform to replace her, but that will take time and give us some breathing room so that we will not have to worry about the marsh walkers for a while.", sourceObjectiveStatus = "unverified-source-field" }
quests[9720] = { id = 9720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Balance Must Be Preserved", description = "I cannot begin to comprehend why the naga would drain the water out of their own habitat.  What I do understand is a need to put a stop to their operations.\n\nThese seeds carry with them the rage of the earth.  Take them to the steam pumps operated by the naga and use them on their controls.\n\nThe vines that grow from the seeds will be as thick as your arm and as strong as iron.  Go, {name}.  Restore the balance that the naga have upset.", sourceObjective = "Ysiel Windsinger wants you to use the Ironvine Seeds on the Steam Pump Controls at Serpent Lake, Umbrafen Lake, Marshlight Lake and the Lagoon. Then return to her at the Cenarion Refuge in Zangarmarsh with any leftover seeds you have.", progress = "Is it done, {class}?", completion = "It is done, then.  The marsh has been saved for now.\n\nDon't think for a second that this will be the last we hear of the naga.  We must remain vigilant of our enemy as we continue with our mission in Outland.", sourceObjectiveStatus = "unverified-source-field" }
quests[9721] = { id = 9721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Summons from Lord Solanar", description = "Your dedication to our order and advancement through the ranks has not gone unnoticed. In fact, Lord Solanar Bloodwrath, Lady Liadrin's right hand and a hero in his own right, has asked to speak with you.\n\nThis is a rare honor, {name}. Normally, Lord Solanar leaves the management of the order's rank-and-file to me, but he has taken a personal interest in you. Do not tarry, {name}.", sourceObjective = "Speak with Lord Solanar Bloodwrath in Silvermoon City.", completion = "We will discuss the purpose for your visit soon. First, let me say that I am indeed impressed by your service and your skill in wielding the Light.", sourceObjectiveStatus = "unverified-source-field" }
quests[9722] = { id = 9722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Master's Path", description = "Within the ranks of our order, there exists an inner circle of elite knights. Members of the circle represent the most dedicated, skilled, and trustworthy of all Blood Knights and are handpicked by the leadership. Most simply know the masters by their thalassian charger mounts.\n\nEach candidate for membership must have a sponsor within the circle and must demonstrate their dedication to the order's central tenets.\n\nI have chosen to sponsor you for standing as a Blood Knight master, if this is your wish.", sourceObjective = "Speak with Lord Solanar Bloodwrath again to accept his offer of sponsorship.", completion = "That you have chosen to accept my offer speaks well of you, {name}. I wish you luck in the tasks I am about to set for you, but I'm certain you'll prove yourself more than capable.\n\nI will present the tasks in order from easiest to most difficult and we may begin when you are prepared.", sourceObjectiveStatus = "unverified-source-field" }
quests[9723] = { id = 9723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gesture of Commitment", description = "A Blood Knight's loyalty does not stop at the end of <his/her> blade, {name}. The order asks more of its members than mere drilling and combat. A true knight contributes to all of the order's activities, even the ones that may not seem glorious on the surface.\n\nThis first task is neither combat intensive, nor glorious, but without such contributions, the order would fall apart. I will give you a list of items Magister Astalor Bloodsworn's men require to keep us supplied with Light energy for our magics.", sourceObjective = "Bring 40 Runecloth, 6 Arcanite Bars, 10 Sungrass, 5 Dark Runes, and 150 Gold to Lord Solanar Bloodwrath in Silvermoon City.", progress = "Have you returned with the materials Magister Astalor requires?", completion = "Excellent. It appears everything is here.\n\nDon't worry, your next task will include plenty of opportunities to wield your weapon again, I promise.\n\nI'll have an initiate bring it all to Magister Astalor. There's no need to send you on such a trivial errand when there are more important things to be done.", sourceObjectiveStatus = "unverified-source-field" }
quests[9724] = { id = 9724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warning the Cenarion Circle", description = "The Cenarion Expedition has become a large organization with a good degree of autonomy.  These events are important enough that we need to warn the Cenarion Circle.\n\nDo not worry, I will not ask you to travel back to Moonglade; we have emissaries as nearby as Hellfire Peninsula.", sourceObjective = "Speak to Amythiel Mistwalker at Cenarion Post in Hellfire Peninsula.", completion = "The news you bring about the naga activity in Zangarmarsh is dire.  Ysiel was wise in sending word to us.  She hasn't forgotten that the Expedition cannot exist without the Circle's support.", sourceObjectiveStatus = "unverified-source-field" }
quests[9725] = { id = 9725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Demonstration of Loyalty", description = "We Blood Knights are bound to defend Quel'Thalas, {name}. This is a central part of your training. Our enemies are fierce and unrelenting. Silvermoon and its people remain free by our efforts and the support of our allies.\n\nI have received some disturbing reports of a renewed Scourge presence to the southeast of our border with the Eastern Plaguelands. A company of Scourge siege engineers and their equipment appear to be staging for an attack on the Ghostlands. They must not be permitted to succeed.", sourceObjective = "Lord Solanar Bloodwrath in Silvermoon City wants you to destroy 3 Scourge Meat Wagons and kill 15 Scourge Siege Engineers.", completion = "You have done well in demonstrating your loyalty to your homeland and dedication to the needs of the order, {name}. I have one last task for you before you may lay claim to the title of master.", sourceObjectiveStatus = "unverified-source-field" }
quests[9726] = { id = 9726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Now That We're Friends...", description = "The naga of the Bloodscale Enclave to the northeast have begun to kill our people.  We cannot allow this to continue, {class}!\n\nWe suggest that you teach them a lesson as proof of our friendship.", sourceObjective = "Kill 12 Bloodscale Slavedrivers and 6 Bloodscale Enchantresses, and then return to Gzhun'tt at Sporeggar in Zangarmarsh.", progress = "Have you paid the naga a visit yet?", completion = "<Gzhun'tt nods to you.>\n\nWe are pleased that you have affirmed our friendship, {name}.  Perhaps the naga heathens will think twice about harassing us in the future now that we have such a powerful ally?", sourceObjectiveStatus = "unverified-source-field" }
quests[9727] = { id = 9727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Now That We're Still Friends...", description = "Reports have come in that the naga of the Bloodscale Enclave to the northeast continue to kill our people.  We thought that you had dealt with this, {class}!\n\nI suggest that you to teach them a lesson as proof of our continued friendship.", sourceObjective = "Kill 12 Bloodscale Slavedrivers and 6 Bloodscale Enchantresses, and then return to Gzhun'tt at Sporeggar in Zangarmarsh.", progress = "Have you paid the naga a visit yet?", completion = "<Gzhun'tt nods to you.>\n\nWe are pleased that you have reaffirmed our friendship, {name}.  Surely now that you have made our point clear multiple times, their senseless attacks upon our people will cease?", sourceObjectiveStatus = "unverified-source-field" }
quests[9728] = { id = 9728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Warm Welcome", description = "While the druids from the expedition have made themselves busy studying plants and researching the lakes, I've made it my business to deal with the hostiles in the area.\n\nEver since we set foot in Zangarmarsh, the naga have launched lethal attacks against us without warning.  We've done our best to keep them at bay, but our resources are limited.\n\nI want you to go to the various naga strongholds in Zangarmarsh and show them that we're not to be crossed.  Bring me their claws as proof of your victories.", sourceObjective = "Warden Hamoot at the Cenarion Refuge wants you to bring him 30 Naga Claws.", progress = "It's good to see you again, {name}.  How's your hunt for the naga going?", completion = "Good job, {name}.  You'd do well to shed any feelings of remorse you might harbor.  These naga are vicious creatures - even more so than the Azerothian ones.", sourceObjectiveStatus = "unverified-source-field" }
quests[9729] = { id = 9729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fhwoor Smash!", description = "Little naga make Fhwoor angry!  Sporelings good friend to Fhwoor, so Fhwoor get naga ark.\n\nWe go into nearby naga village.  You help?  Bring friends!", sourceObjective = "Escort Fhwoor into the area of the Marshlight steam pump to retrieve the Ark of Ssslith. Bring Fhwoor and the ark back safely and then report back to Gzhun'tt at Sporeggar in Zangarmarsh.", progress = "Is Fwhoor alright?  Have you recovered the ark?", completion = "Fhwoor's a good giant.  We saved him from the naga a while ago and he's stayed here helping us with things ever since.\n\nWe can only hope that the naga will take the hint and realize that if we can infiltrate their village and steal their most prized possession, we can do much worse.  Perhaps now they will return to their reservoir and leave us in peace?", sourceObjectiveStatus = "unverified-source-field" }
quests[9730] = { id = 9730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leader of the Darkcrest", description = "A bounty is hereby declared by the Cenarion Expedition on Rajah Haghazed, leader of the Darkcrest naga.  Haghazed was last sighted by Cenarion scouts at the Lagoon, in the central southern region of Zangarmarsh.\n\nThe Darkcrest have been linked to numerous attacks against the Cenarion Expedition and their leader is considered extremely dangerous.\n\nThose seeking to claim the bounty are advised to report to Warden Hamoot.", sourceObjective = "Slay Rajah Haghazed at the Lagoon and return to Warden Hamoot at the Cenarion Expedition in Zangarmarsh for a reward.", progress = "You want to talk about the bounty for Haghazed?  Well, is he dead?  There isn't much else to talk about!", completion = "I didn't like the naga in Azeroth and I like them less here.  It's a real shame our mission could not remain a peaceful one, but you won't see me shedding tears for dead naga.\n\nHere's your reward for taking care of the Darkcrest leader, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9731] = { id = 9731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drain Schematics", description = "The schematics you've obtained show an underground system of drains and pumps that connect the lakes in the region to Serpent Lake.\n\nIf the schematics are correct, there is a giant drain in the center of Serpent Lake.  Confirm this and bring the news to Cenarion Refuge.", sourceObjective = "Search Serpent Lake for signs of a drain. Return to Ysiel Windsinger at the Cenarion Refuge with news of your discovery.", progress = "What news do you bring, {name}?", completion = "The naga have turned Serpent Lake into a giant water sink for the rest of Zangarmarsh.  What could they possibly be doing?\n\nYou've done well in bringing this news to us, {name}.  We will send a team to investigate this drain you've discovered.  I have a different task for you in the meanwhile.", sourceObjectiveStatus = "unverified-source-field" }
quests[9732] = { id = 9732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Marsh", description = "Return to Ysiel and let her know that help will be extended to her as soon as it is possible.\n\nAffairs in Moonglade and Silithus have kept our members occupied, but we will do our best to send the necessary resources to the Cenarion Refuge.", sourceObjective = "Return to Ysiel Windsinger at the Cenarion Refuge in Zangarmarsh.", completion = "You are a welcome sight, {name}.  Matters at the Cenarion Refuge have only gotten worse since you left.", sourceObjectiveStatus = "unverified-source-field" }
quests[9733] = { id = 9733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warning the Cenarion Circle", description = "The Cenarion Expedition has become a large organization with a good degree of autonomy.  These events are important enough that we need to warn the Cenarion Circle.\n\nDo not worry, I will not ask you to travel back to Moonglade; we have emissaries as nearby as Hellfire Peninsula.", sourceObjective = "Speak to Mahuram Stouthoof at Thrallmar in Hellfire Peninsula.The Cenarion Expedition has become a large organization with a good degree of autonomy. These events are important enough that we need to warn the Cenarion Circle.\n\nDo not worry, I will not ask you to travel back to Moonglade; we have emissaries as nearby as Hellfire Peninsula.", sourceObjectiveStatus = "unverified-source-field" }
quests[9734] = { id = 9734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Marsh", description = "Return to Ysiel and let her know that help will be extended to her as soon as it is possible.\n\nAffairs in Moonglade and Silithus have kept our members occupied, but we will do our best to send the necessary resources to the Cenarion Refuge.You will be able to choose one of these rewards:", sourceObjective = "Return to Ysiel Windsinger at the Cenarion Refuge in Zangarmarsh.", sourceObjectiveStatus = "unverified-source-field" }
quests[9735] = { id = 9735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "True Masters of the Light", description = "A Blood Knight master possesses incredible skill at wielding and weaving the Light in a way that other so-called 'paladins' can never comprehend. It doesn't stop them from despising us for unleashing the Light's true potential.\n\nWe must send them a message and show them that we are not to be trifled with. What I have in mind will be neither brief nor easy, but if you are committed, the first step will be to infiltrate the library wing of the Tyr's Hand Abbey and procure a vial of Tyr's Hand holy water.", sourceObjective = "Lord Solanar Bloodwrath in Silvermoon City wants you to bring him a vial of Tyr's Hand Holy Water.", progress = "Were you able to get the water?", completion = "Hmm... this is a rather small amount, but if we're careful, it should be sufficient. You see, the Scarlet Crusade believes itself dedicated to the Light. I suppose they still are, in a twisted sort of way, and that's exactly what I'm hoping to capitalize on.\n\nTheir misguided zeal has even tainted the blessing spoken over this water, making it ideal for our purpose.", sourceObjectiveStatus = "unverified-source-field" }
quests[9736] = { id = 9736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "True Masters of the Light", description = "Now that we have the water, we're going to need a number of reagents in precise quantities. Some of these substances are rare and expensive, {name}, but I have located sources for two.\n\nYou should be able to purchase some arcane catalyst from Zalle, the reagent vendor in one of the shops on the plaza near the Dead Scar. Darlia, the poison merchant near the rogue trainers on Murder Row, stocks crepuscular powder.\n\nTo complete my mixture, I'll also need an azerothian diamond and a pristine black diamond.", sourceObjective = "Lord Solanar Bloodwrath in Silvermoon City wants you to bring him 1 Arcane Catalyst, 1 Crepuscular Powder, 1 Azerothian Diamond, and 1 Pristine Black Diamond.", progress = "Have you gathered the reagents I'll need?", completion = "Now that we have all the reagents, I can prepare the mixture.\n\n<A slow smile spreads across Lord Solanar's face.>\n\nIt's all coming together perfectly, {name}. When this is finished, I'll give you the details about what remains to be done.", sourceObjectiveStatus = "unverified-source-field" }
quests[9737] = { id = 9737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "True Masters of the Light", description = "Ours is the true way of utilizing the Light, {name}. To show others that would call themselves 'paladins' the folly of their ways, I intend to send an unmistakable message.\n\nThe Alonsus Chapel, where the Order of the Silver Hand was founded, seems immune to the destruction of Stratholme. The chapel's eternal flame affords it the Light's protection, but when you use this mixture to extinguish the flame, that protection will be no more. It will burn, and our dominion over the Light will be proven to the world.", sourceObjective = "Use the Extinguishing Mixture near the eternal flame in the Alonsus Chapel to remove the Light's protection. Be prepared to fight anyone who may attempt to defend the chapel.", progress = "Have you done as I asked and delivered my message? The false paladins of the world must surely know their time has come to an end.", completion = "Well done, {name}. All who would oppose us would do well to heed the warning you delivered. Our foes should know that they are in peril, from the lowest foot soldier to the mightiest hero.\n\nYou have earned your place in the ranks of the masters. Your dedication and prowess serve as an example for all Blood Knights. As a symbol of your new status, I grant you the ability to summon and command the thalassian charger.", sourceObjectiveStatus = "unverified-source-field" }
quests[9738] = { id = 9738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost in Action", description = "You have to help me!  We were sent here by Ysiel to investigate the mystery of the steam pumps and why they're being used to drain the water from the marsh.  But my friends split up and went on recklessly without me.\n\nThose four can be such jerks sometimes, but I love them anyway.\n\nThat is why I need you to discover what became of them, though I fear the worst.  Seek them in both the Slave Pens and the Underbog.\n\nThank you, {class}.", sourceObjective = "Discover what happened to Earthbinder Rayge, Naturalist Bite, Weeder Greenthumb, and Windcaller Claw. Then, return to Watcher Jhang at Coilfang Reservoir in Zangarmarsh.", progress = "Have you discovered the whereabouts of my four companions yet?", completion = "I'm glad that some of my friends yet live, but it breaks my heart to hear of the fate of others.  <sigh>\n\nAt least they died doing what they loved most in life.  You have my eternal gratitude for helping me with this, {name}.\n\nPlease, take one of these as a sign of gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[9739] = { id = 9739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sporelings' Plight", description = "You there!  You must help us!\n\nThe fungal giants are devouring all of our spore sacs!  You must do something, or we'll lose our young!\n\nThe spore sacs start out large and become smaller as the air inside them is depleted.  Look for the small, mature spore sacs and save as many of them as you can!", sourceObjective = "Fahssn at the Spawning Glen wants you to collect 10 Mature Spore Sacs.", progress = "The spore sacs!  Did you get them?", completion = "You've done it!  You have my people's thanks.\n\nI hope you understand... this is where our young ones come from.  We can't let these beasts devour the sacs!", sourceObjectiveStatus = "unverified-source-field" }
